// ===== menus =====
const $=s=>document.querySelector(s);
const KEY='cityGridiron.v2';
const UI={quick:null,two:null,tab:'home',rf:'ALL',rv:'team',sel:null,edMsg:'',faMsg:'',setup:null,dpos:'ALL',tr:{team:-1,give:[],get:[],gk:[],tk:[],msg:'',ok:false},confirmNew:false};
const coarse=window.matchMedia&&matchMedia('(pointer:coarse)').matches;
// Franchise and Be a Pro keep separate saves; the last one used opens first.
const KEYP='cityGridiron.pro',KEYL='cityGridiron.last';
function save(){if(!S||S.user<0)return;S.nid=NID;try{localStorage.setItem(S.mode==='pro'?KEYP:KEY,JSON.stringify(S));localStorage.setItem(KEYL,S.mode==='pro'?'p':'f');}catch(e){}}
function loadKey(k){try{const s=localStorage.getItem(k);if(s){const o=JSON.parse(s);if(o&&(o.v>=2&&o.v<=6)&&o.teams&&o.teams.length===32&&o.user>=0){S=o;NID=S.nid||1;if(S.v<6){migrate();save();}return true;}}}catch(e){}return false;}
function load(which){let w=which;if(!w){try{w=localStorage.getItem(KEYL);}catch(e){}w=w||'f';}const ok=loadKey(w==='p'?KEYP:KEY)||(!which&&loadKey(w==='p'?KEY:KEYP));if(ok){try{localStorage.setItem(KEYL,S.mode==='pro'?'p':'f');}catch(e){}}return ok;}
const hasSave=k=>{try{return !!localStorage.getItem(k);}catch(e){return false;}};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sw=(T,c)=>`<span class="sw${c?' '+c:''}" style="--a:${T.c1};--b:${T.c2}"></span>`;
const byId=(T,id)=>T.roster.find(p=>p.id===id);
const pkById=id=>S.picks.find(k=>k.id===id);
const posRank=p=>POS_ORDER.indexOf(p.pos)*1000-p.ovr;
const xfTag=p=>p.xf?' <span class="xf" title="X-Factor: '+xfName(p)+'">X</span>':'';
const devTag=p=>`<span class="dev d${p.dev}">${DEV[p.dev]}</span>`;
const phaseName=()=>S.phase==='regular'?'Week '+(S.week+1):S.phase==='playoffs'?roundName():S.phase==='draft'?S.draft.yr+' draft':S.phase==='preseason'?'Preseason':'Offseason';
const FILT={ALL:POS_ORDER,OFF:['QB','RB','WR','TE','OL'],DEF:['DL','LB','CB','S'],K:['K']};

function render(){if(!S||S.user<0){renderPick();return;}if(isPro()){renderPro();return;}const U=S.teams[S.user];
  $('#top').innerHTML=`<div class="who">${sw(U,'lg')}<div><h1>${U.name}</h1><div class="meta">${S.season} · ${phaseName()} · ${U.w}-${U.l}</div></div></div><div class="stat">${S.tp}<small>Training points</small></div>`;
  $('#tabs').hidden=false;$('#tabs').innerHTML=[['home',S.phase==='draft'?'Draft':'Home'],['roster','Roster'],['trade','Trades'],['league','League']].map(t=>`<button data-a="tab" data-t="${t[0]}" class="${UI.tab===t[0]?'on':''}">${t[1]}</button>`).join('');
  ({home:vHome,roster:vRoster,trade:vTrade,league:vLeague})[UI.tab]();}
function renderPick(){if(!S)newLeague();
  $('#top').innerHTML='<div class="who"><div><h1>City Gridiron</h1><div class="meta">'+(UI.proNew?'Create your player':'Pick a city to run')+'</div></div></div>';$('#tabs').hidden=true;
  if(UI.proNew){$('#view').innerHTML='<div class="wrap">'+proNewCard()+'</div>';return;}
  let h='<div class="wrap">'+quickCard()+'<section class="card hero"><p class="eyebrow">New franchise</p><h2>Thirty-two cities. One trophy.</h2><p class="muted">Call the plays, throw the passes, play defense, and trade players and draft picks to build a winner. Pick your city below.</p></section>'+proCard();
  for(const c of ['A','N']){h+=`<section><h3>${CONF[c]} conference</h3><div class="pick">`;
    for(const d of DIVS)for(const T of S.teams.filter(t=>t.conf===c&&t.div===d)){const r=ratings(T);h+=`<button data-a="pick" data-id="${T.id}">${sw(T)}<span><b>${T.name}</b><small>${d} · ${r.ovr} overall</small></span></button>`;}
    h+='</div></section>';}
  $('#view').innerHTML=h+'</div>';}
function teamBlock(T,r){return `<div class="tb">${sw(T,'lg')}<div><b>${T.name}</b><span>${T.w}-${T.l}</span><div class="chips"><span class="chip">OFF ${r.off}</span><span class="chip">DEF ${r.def}</span></div></div></div>`;}

// ----- uniforms -----
function uniSvg(T,key){const u=uniOf(T)[key];return `<svg viewBox="0 0 44 70" aria-hidden="true"><rect x="14" y="44" width="16" height="16" fill="${u[2]}" stroke="#0006" stroke-width=".6"/><rect x="15" y="60" width="5" height="8" fill="${lum(u[0])>0.8?u[4]:u[0]}"/><rect x="24" y="60" width="5" height="8" fill="${lum(u[0])>0.8?u[4]:u[0]}"/>
  <path d="M4 18h36v10h-6v17H10V28H4z" fill="${u[0]}" stroke="#0006" stroke-width=".6"/><rect x="4" y="24" width="6" height="3" fill="${u[4]}"/><rect x="34" y="24" width="6" height="3" fill="${u[4]}"/>
  <text x="22" y="39" text-anchor="middle" font-size="13" font-weight="700" font-family="Barlow Condensed,Arial Narrow,sans-serif" fill="${u[1]}">12</text>
  <rect x="13" y="2" width="18" height="15" rx="6" fill="${u[3]}" stroke="#0006" stroke-width=".6"/><rect x="21" y="2" width="2" height="15" fill="${u[4]}"/><rect x="17" y="12" width="10" height="3.5" fill="#22262b"/></svg>`;}
function fixClash(T,key,other){const j=uniOf(other.T)[other.key][0];if(colDist(uniOf(T)[key][0],j)>=110)return key;
  let best=key,bd=-1;for(const k of ['A','H','X','R']){const d=colDist(uniOf(T)[k][0],j);if(d>bd){bd=d;best=k;}}return best;}
function openSetup(){const m=userMatch();if(!m)return;const home=m.h===S.user,U=S.teams[S.user],O=S.teams[home?m.a:m.h];
  const uU=home?'H':fixClash(U,'A',{T:O,key:'H'});UI.setup={home,opp:O.id,uU,uO:fixClash(O,home?'A':'H',{T:U,key:uU})};}
function uniPicker(T,cur,side){return `<div class="unicol"><h3>${T.name}</h3><div class="unirow">`+['H','A','X','R'].map(k=>`<button class="uni${cur===k?' on':''}" data-a="uni" data-s="${side}" data-k="${k}" aria-pressed="${cur===k}">${uniSvg(T,k)}<span>${UNI_NAMES[k]}</span></button>`).join('')+'</div></div>';}
function settingsRow(){const sel=(id,lab,opts,cur)=>`<span class="setp"><label for="${id}">${lab}</label><select id="${id}">${opts.map((o,i)=>`<option value="${i}"${cur===i?' selected':''}>${o}</option>`).join('')}</select></span>`;
  return '<div class="row set">'+sel('setDiff','Difficulty',DIFFS,S.diff)+sel('setSpeed','Game speed',SPEEDS,S.speed)+sel('setDef','Defense',['Simulate defense','I play defense'],S.playDef?1:0)+sel('setKo','Kickoffs',['Skip returns','Play returns'],S.koRet?1:0)+sel('setTalk','Broadcast crew',['Off','Captions only','Voice and captions','Voice only'],S.talk)+sel('setQlen','Quarter length',QLENS.map(m=>m+' minutes'),Math.max(0,QLENS.indexOf(S.qlen||4)))+'</div>';}
const QLENS=[2,3,4,5,6,8];
function setupCard(lab){const su=UI.setup,U=S.teams[S.user],O=S.teams[su.opp],rival=U.conf===O.conf&&U.div===O.div;
  const clash=colDist(UNI[U.abbr][su.uU][0],UNI[O.abbr][su.uO][0])<110;
  return `<section class="card hero"><p class="eyebrow">${lab} · ${su.home?'Home':'Away'}${rival?' · Division rivalry game':''}</p><h2>Pick the uniforms</h2>
  <div class="unis">${uniPicker(U,su.uU,'U')}${uniPicker(O,su.uO,'O')}</div>${clash?'<p class="bad">These two jerseys look alike. Pick a different one for either team.</p>':''}
  ${settingsRow()}<div class="row"><button class="btn" data-a="kickoff">Kick off</button><button class="btn ghost" data-a="setupBack">Back</button></div></section>`;}

function awardsCard(){const A=S.awards;if(!A)return '';const me=t=>t===S.user?' class="me"':'';
  return `<section class="card"><h3>${A.yr} season awards</h3><ul class="news">${A.list.map(a=>`<li${me(a.team)}><b>${a.t}:</b> ${a.pos} ${esc(a.n)}, ${S.teams[a.team].name} <span class="muted">${a.line}</span></li>`).join('')}</ul><p class="eyebrow">All-Pro team</p><p>${A.pro.map(a=>`<span${me(a.team)}>${a.pos} ${esc(a.n)} <span class="muted">${S.teams[a.team].abbr}</span></span>`).join(' · ')}</p></section>`;}
function leadersCard(){const L=Object.values(S.pst||{});if(!L.length)return '';const top=(k,min)=>L.filter(x=>(x[k]||0)>=min).sort((a,b)=>b[k]-a[k])[0],rows=[];
  let x=top('py',1);if(x)rows.push(`<li><b>Passing:</b> ${esc(x.n)} · ${x.cmp} of ${x.att}, ${x.py} yards, ${x.ptd} touchdowns, ${x.pint} interceptions</li>`);
  x=top('ry',1);if(x)rows.push(`<li><b>Rushing:</b> ${esc(x.n)} · ${x.car} carries, ${x.ry} yards, ${x.td} touchdowns</li>`);
  x=top('recy',1);if(x)rows.push(`<li><b>Receiving:</b> ${esc(x.n)} · ${x.rec} catches, ${x.recy} yards</li>`);
  x=top('tk',1);if(x)rows.push(`<li><b>Tackles:</b> ${esc(x.n)} · ${x.tk}</li>`);x=top('sk',1);if(x)rows.push(`<li><b>Sacks:</b> ${esc(x.n)} · ${x.sk}</li>`);x=top('int',1);if(x)rows.push(`<li><b>Interceptions:</b> ${esc(x.n)} · ${x.int}</li>`);
  return rows.length?`<section class="card"><h3>Your team leaders</h3><p class="muted">From the games you played this season.</p><ul class="news">${rows.join('')}</ul></section>`:'';}
function voiceRow(){const v=voiceList(),cur=S.voice||['',''],lab=x=>esc(x.name.replace(/^(Microsoft|Google|Apple) /,'').replace(/ Online \(Natural\).*/,' (Natural)'))+' · '+esc(/^en/i.test(x.lang)?x.lang.replace('_','-').slice(3):x.lang),
    opt=c=>'<option value="">Best available</option>'+v.map(x=>`<option value="${esc(x.name)}"${x.name===c?' selected':''}>${lab(x)}</option>`).join(''),
    sel=(id,l,c)=>`<span class="setp"><label for="${id}">${l}</label><select id="${id}" class="vsel">${opt(c)}</select></span>`,
    one=(id,l,o,ci)=>`<span class="setp"><label for="${id}">${l}</label><select id="${id}">${o.map((t,i)=>`<option value="${i}"${ci===i?' selected':''}>${t}</option>`).join('')}</select></span>`,
    crowd=one('setCrowd','Crowd noise',['Off','On'],S.crowd===false?0:1);
  if(!v.length)return '<div class="row set">'+crowd+'</div><p class="muted">The announcer voices come from your browser or device. None are available here, so the booth shows captions only.</p>';
  return '<div class="row set">'+sel('setV0','Ray, play-by-play',cur[0])+sel('setV1','Tony, analyst',cur[1])+one('setVspd','Pace',['Relaxed','Normal','Fast'],S.vspd==null?1:S.vspd)+crowd+'<button class="btn ghost sm" data-a="voiceTest">Hear them</button></div><p class="muted">The game picks the most natural voices your browser has, listed best first. The voices themselves come from your browser or device: Microsoft Edge has the most lifelike ones, marked Natural.</p>';}
// ----- practice, two-player, history -----
function practiceCard(){const done=k=>drillDone(k);return `<section class="card"><h3>Practice</h3><p class="muted">Quick drills that pay up to 2 training points each, once a week.</p><div class="drills">${Object.keys(DRILLS).map(k=>`<button class="drill${done(k)?' done':''}" data-a="drill" data-k="${k}"><b>${DRILLS[k][0]}</b><small>${DRILLS[k][1]}</small><span>${done(k)?'Done this week':'Up to +2'}</span></button>`).join('')}</div></section>`;}
function quickCard(){const Q=UI.quick;if(!Q)return `<section class="card"><h3>Quick game</h3><p class="muted">One game against the computer with any two teams. Short quarters, and it doesn't count toward a season.</p><div class="row"><button class="btn ghost" data-a="quick">Set up a quick game</button></div></section>`;
  const opt=sel=>S.teams.map(t=>`<option value="${t.id}"${t.id===sel?' selected':''}>${t.name}</option>`).join(''),sel=(id,lab,opts,cur)=>`<span class="setp"><label for="${id}">${lab}</label><select id="${id}">${opts.map((o,i)=>`<option value="${i}"${cur===i?' selected':''}>${o}</option>`).join('')}</select></span>`;
  return `<section class="card hero"><p class="eyebrow">Quick game</p><h2>${esc(S.teams[Q.u].name)} vs ${esc(S.teams[Q.o].name)}</h2><div class="row set"><span class="setp"><label for="qkU">Your team</label><select id="qkU">${opt(Q.u)}</select></span><span class="setp"><label for="qkO">Opponent</label><select id="qkO">${opt(Q.o)}</select></span>${sel('qkQl','Quarters',QLENS.map(m=>m+' minutes'),Math.max(0,QLENS.indexOf(Q.ql)))}${sel('setDiff','Difficulty',DIFFS,S.diff)}</div>
  ${Q.u===Q.o?'<p class="bad">Pick two different teams.</p>':''}<div class="row"><button class="btn" data-a="quickStart"${Q.u===Q.o?' disabled':''}>Kick off</button><button class="btn ghost" data-a="quickBack">Cancel</button></div></section>`;}
function twoCard(){const T=UI.two;if(!T)return `<section class="card"><h3>Two-player game</h3><p class="muted">Two people, one keyboard, any two teams. It doesn't count toward your season.</p><div class="row"><button class="btn ghost" data-a="two">Set up a two-player game</button></div></section>`;
  const opt=sel=>S.teams.map(t=>`<option value="${t.id}"${t.id===sel?' selected':''}>${t.name}</option>`).join(''),H=S.teams[T.h],A=S.teams[T.a];
  return `<section class="card hero"><p class="eyebrow">Two-player game</p><h2>${esc(H.name)} vs ${esc(A.name)}</h2>
  <div class="row set"><span class="setp"><label for="twoH">Player 1 (home)</label><select id="twoH">${opt(T.h)}</select></span><span class="setp"><label for="twoA">Player 2 (away)</label><select id="twoA">${opt(T.a)}</select></span></div>
  <div class="keys"><div><b>Player 1</b><span>Move: W A S D</span><span>Snap, juke, tackle: Space</span><span>Spin: E · Switch: Q · Pitch: G</span><span>Throw / pick: 1-5 · Timeout: T</span></div><div><b>Player 2</b><span>Move: arrow keys</span><span>Snap, juke, tackle: Enter</span><span>Spin: / · Switch: . · Pitch: ;</span><span>Throw / pick: 6 7 8 9 0 · Timeout: P</span></div></div>
  <p class="muted">The offense picks a play first, then the defense picks a call while the other player looks away. Best on a computer keyboard.</p>
  ${T.h===T.a?'<p class="bad">Pick two different teams.</p>':''}<div class="row"><button class="btn" data-a="twoStart"${T.h===T.a?' disabled':''}>Kick off</button><button class="btn ghost" data-a="twoBack">Cancel</button></div></section>`;}
function careerTable(p){const H=(p.hist||[]).slice(-8),cur=S.pst[p.id];if(!H.length&&!cur)return '';const cols=p.pos==='QB'?[['py','Pass yds'],['ptd','TD'],['pint','INT']]:p.pos==='RB'?[['ry','Rush yds'],['td','TD'],['rec','Rec']]:p.pos==='WR'||p.pos==='TE'?[['rec','Rec'],['recy','Yds'],['td','TD']]:p.pos==='DL'||p.pos==='LB'?[['tk','Tkl'],['sk','Sacks'],['int','INT']]:p.pos==='CB'||p.pos==='S'?[['tk','Tkl'],['int','INT'],['pd','PD']]:p.pos==='K'?[['fgm','FG'],['fga','Att']]:[];
  const row=(y,t,o,s)=>`<tr><td class="l">${y}</td><td>${t}</td><td>${o}</td>${cols.map(c=>`<td>${s[c[0]]!=null?Math.round(s[c[0]]*10)/10:0}</td>`).join('')}</tr>`;
  return `<div class="scroll"><table class="tbl sm"><thead><tr><th class="l">Season</th><th>Team</th><th>Ovr</th>${cols.map(c=>`<th>${c[1]}</th>`).join('')}</tr></thead><tbody>${H.map(h=>row(h.y,h.t,h.o,h.s)).join('')}${cur?row(S.season+' (your games)',S.teams[S.user].abbr,p.ovr,cur):''}</tbody></table></div>`;}
function historyCards(){let h='';const R=S.rec||{},fmt=v=>Math.round(v*10)/10>=1000?Math.round(v).toLocaleString('en-US'):Math.round(v*10)/10;
  if(R.s&&Object.keys(R.s).length){h+=`<section class="card"><h3>League records</h3><div class="tr-cols"><div><p class="eyebrow">Single season</p><ul class="news">${REC_KEYS.filter(k=>R.s[k[0]]).map(k=>{const r=R.s[k[0]];return `<li><b>${k[1]}:</b> ${fmt(r.v)} · ${esc(r.n)} (${r.t}, ${r.y})</li>`;}).join('')}</ul></div><div><p class="eyebrow">Career</p><ul class="news">${REC_KEYS.filter(k=>R.c&&R.c[k[0]]).map(k=>{const r=R.c[k[0]];return `<li><b>${k[1]}:</b> ${fmt(r.v)} · ${esc(r.n)}</li>`;}).join('')}</ul></div></div><p class="muted">Records start with the ${S.hist&&S.hist.length?S.hist[S.hist.length-1].y:S.season} season.</p></section>`;}
  if(S.hof&&S.hof.length)h+=`<section class="card"><h3>Hall of Fame</h3><ul class="news">${S.hof.slice(0,20).map(x=>`<li${x.user?' class="me"':''}><b>${x.pos} ${esc(x.n)}</b> · Class of ${x.y} · ${x.teams.join(', ')} <span class="muted">${esc(x.line)}${x.aw?', '+x.aw+' honors':''}</span></li>`).join('')}</ul></section>`;
  else h+='<section class="card"><h3>Hall of Fame</h3><p class="muted">Empty so far. Stars who retire with big careers, awards and All-Pro seasons get in.</p></section>';
  if(S.hist&&S.hist.length)h+=`<section class="card"><h3>Champions</h3><ul class="news">${S.hist.slice(0,15).map(x=>`<li${x.champ===S.user?' class="me"':''}><b>${x.y}:</b> ${S.teams[x.champ].name} beat ${S.teams[x.ru].name} ${x.sc}${x.mvp?' <span class="muted">· MVP '+esc(x.mvp)+'</span>':''}</li>`).join('')}</ul></section>`;
  return h;}
function audPanel(g){if(g.aud==='list'){const cur=g.play;g.audList=pickPlays(situation(),6).filter(p=>p!==cur).slice(0,4);
    return `<div class="row"><b class="res">Audible</b>${g.audList.map((p,i)=>`<button class="btn sm" data-a="audPick" data-i="${i}"><span class="kbd">${i+1}</span>${p.n}</button>`).join('')}<button class="btn ghost sm" data-a="audClose">Keep the play</button></div>`;}
  const pool=['WR1','WR2','WR3','TE','RB'].map(r=>g.by[r]).filter(Boolean),used=new Set(g.elig.map(e=>e.key));for(const e of pool)if(!g.elig.includes(e)){let k=1;while(used.has(k))k++;e.key=k;used.add(k);}g.hotPool=pool;
  if(g.audK==null)return `<div class="row"><b class="res">Hot route</b><span class="muted">Pick a player:</span>${pool.sort((a,b)=>a.key-b.key).map(e=>`<button class="btn sm" data-a="hotPick" data-k="${e.key}"><span class="kbd" style="background:${RCOL[(e.key-1)%5]};color:#141a12">${e.key}</span>#${e.num} ${e.rp.pos}${g.elig.includes(e)?'':' (blocking)'}</button>`).join('')}<button class="btn ghost sm" data-a="audClose">Cancel</button></div>`;
  return `<div class="row"><b class="res">New route for player ${g.audK}</b>${HOT.map((r,i)=>`<button class="btn sm" data-a="hotRoute" data-i="${i}"><span class="kbd">${i+1}</span>${r[0]}</button>`).join('')}<button class="btn ghost sm" data-a="audClose">Cancel</button></div>`;}
// ----- home -----
function assetLine(T,ids,kids){return ids.map(id=>byId(T,id)).map(p=>`<b>${p.pos} ${esc(p.n)}</b>${xfTag(p)} <span class="muted">${p.ovr} overall, age ${p.age}</span>`).concat(kids.map(id=>`<b>${pickName(pkById(id))} pick</b>`)).join(', ');}
function offerCard(){const o=S.offer;if(!o||!tradesOpen())return '';const T=S.teams[o.team],U=S.teams[S.user];
  if(o.give.some(id=>!byId(U,id))||o.get.some(id=>!byId(T,id))||o.giveK.some(id=>!pkById(id)||pkById(id).own!==U.id)||o.getK.some(id=>!pkById(id)||pkById(id).own!==T.id)){S.offer=null;return '';}
  return `<section class="card"><p class="eyebrow">Trade offer from ${T.name}</p><p>They send ${assetLine(T,o.get,o.getK)}</p><p>They want ${assetLine(U,o.give,o.giveK)}</p><div class="row"><button class="btn sm" data-a="offerYes">Accept</button><button class="btn ghost sm" data-a="offerNo">Decline</button></div></section>`;}
function vHome(){if(S.phase==='draft')return vDraft();const U=S.teams[S.user],r=ratings(U);let h='<div class="wrap">';
  if(S.phase==='offseason'){const ch=S.teams[S.champ];
    h+=`<section class="card hero"><p class="eyebrow">${S.season} season complete</p><h2>${ch.id===S.user?'You won the Gridiron Bowl':ch.name+' won the Gridiron Bowl'}</h2><p class="muted">Trades and free agency are open. When you start the draft, every player ages a year first: young players improve at a pace set by their potential, veterans decline, and some retire.</p><div class="row"><button class="btn" data-a="startDraft">Start the ${S.season+1} draft</button></div></section>`;}
  else if(S.phase==='preseason'){const over=U.roster.length-ROSTER_MAX;
    h+=`<section class="card hero"><p class="eyebrow">Draft complete</p><h2>Ready for ${S.season+1}</h2><p class="muted">You have ${U.roster.length} players. The limit is ${ROSTER_MAX}. Trades and free agency are open, and undrafted rookies are in the free agent pool.</p>${over>0?`<p class="bad">Release ${over} player${over>1?'s':''} on the Roster tab before the season starts.</p>`:''}<div class="row"><button class="btn" data-a="newSeason"${over>0?' disabled':''}>Start ${S.season+1} season</button></div></section>`;}
  else{const m=userMatch(),lab=S.phase==='regular'?'Week '+(S.week+1)+' of '+S.schedule.length:roundName();
    if(m&&UI.setup)h+=setupCard(lab);
    else if(m){const home=m.h===S.user,opp=S.teams[home?m.a:m.h],rival=U.conf===opp.conf&&U.div===opp.div;
      h+=`<section class="card hero"><p class="eyebrow">${lab} · ${home?'Home':'Away'}${rival?' · Division game':''}</p><div class="match">${teamBlock(U,r)}<span class="vs">${home?'vs':'at'}</span>${teamBlock(opp,ratings(opp))}</div><div class="row"><button class="btn" data-a="play">Play game</button><button class="btn ghost" data-a="sim">Sim game</button></div></section>`;}
    else if(S.phase==='regular')h+=`<section class="card hero"><p class="eyebrow">${lab}</p><h2>Bye week</h2><p class="muted">No game for you this week. The rest of the league plays on.</p><div class="row"><button class="btn" data-a="sim">Continue</button></div></section>`;
    else{const alive=S.po&&(S.po.alive.A.includes(S.user)||S.po.alive.N.includes(S.user));
      h+=`<section class="card hero"><p class="eyebrow">${lab}</p><h2>${alive?'You earned a first-round bye':'Your season is over'}</h2><div class="row"><button class="btn" data-a="sim">${alive?'Continue':'Sim this round'}</button></div></section>`;}}
  if(UI.two)h=h.replace('<div class="wrap">','<div class="wrap">'+twoCard());if(UI.quick)h=h.replace('<div class="wrap">','<div class="wrap">'+quickCard());
  h+=offerCard();if(S.phase==='offseason'||S.phase==='preseason')h+=awardsCard();if(!UI.setup){h+=practiceCard();if(!UI.quick)h+=quickCard();if(!UI.two)h+=twoCard();h+=proCard();}
  if(S.news.length)h+='<section class="card"><h3>News</h3><ul class="news">'+S.news.slice(0,8).map(n=>`<li>${esc(n)}</li>`).join('')+'</ul></section>';
  if(!UI.setup)h+=`<section class="card"><h3>Settings</h3>${settingsRow()}<p class="muted">Rookie is forgiving. Legend makes defenders faster to react, tackles surer, and the other team's quarterback sharper.</p></section><section class="card"><h3>Broadcast sound</h3>${voiceRow()}</section>`;
  h+=`<section class="card"><h3>How to play</h3><ul class="news"><li><b>Offense:</b> the coach suggests plays for the situation, or open the full playbook by type. Snap with <b>Space</b> or a tap, move with <b>WASD</b> or the arrow keys (drag on a phone). Each receiver has his own route color and number; press the number or tap him to throw. <b>Space</b> jukes.</li><li><b>Defense:</b> pick a coverage, then steer the player with the blue marker. Run into the ball carrier to tackle, press <b>Space</b> to dive at him, or press it as a pass arrives to swat it. <b>Q</b> switches to the defender nearest the ball.</li><li><b>After a touchdown:</b> choose a celebration, then kick the extra point or go for two.</li><li><b>X-Factors:</b> stars marked X switch on after a couple of good plays, shown by a gold ring and X. The bar at the bottom of the field shows who has the ball and whether his ability is on.</li><li><b>Clock:</b> after a play that ends in bounds the game clock keeps running while you pick the next play. Snap before the play clock hits zero or it's delay of game. Each team has 3 timeouts per half (press <b>T</b>). <b>Sim drive</b> plays out the rest of a possession for you.</li><li><b>Ball carrier moves:</b> Space jukes, E or F spins. Pick off a pass and you run it back.</li><li><b>Injuries:</b> now and then a player gets hurt and misses a few weeks. His backup starts until he's healthy.</li><li><b>Playbook:</b> two-back sets (Pro I, Split backs) and a Trick plays tab with a flea flicker, a reverse, hook and lateral, and, on fourth down, fake punts and fake field goals. At the line, Audible changes the play and Hot route changes one player's route.</li><li><b>Laterals and fumbles:</b> press <b>L</b> (or Pitch) to pitch the ball back to a teammate. Hard hits can knock the ball loose; steer your player onto it to recover.</li><li><b>Clock tools:</b> Hurry-up (<b>H</b>) keeps less time running between plays, Spike (<b>K</b>) stops the clock for a down, and you can try an onside kick when you kick off.</li><li><b>Weather:</b> rain and snow make the ball harder to throw, catch and hold; wind moves passes and kicks. Domes stay dry. Some games are at night.</li><li><b>Replays:</b> after any play press <b>R</b> (or Replay) to watch it again from four camera angles, in slow motion. After the game, watch the highlights.</li><li><b>Flags:</b> when the other team commits a foul you choose to accept the yards or decline and keep the play.</li><li><b>Captains and returner:</b> on the Roster tab, tap a player to make him a captain (up to 4, each plays 2 points better) or your kick returner.</li><li><b>Training points:</b> earned every game. Spend them on the Roster tab to raise ratings or sign free agents.</li></ul><div class="row"><button class="btn ghost sm" data-a="newFr">${UI.confirmNew?'Tap again to erase this franchise':'Start a new franchise'}</button></div></section>`;
  $('#view').innerHTML=h+'</div>';}

// ----- roster, free agents and player editor -----
function editor(U){const p=byId(U,UI.sel);if(!p){UI.sel=null;return '';}const c=upgradeCost(p);
  return `<section class="card edit"><div class="row"><h3>${esc(p.n)}</h3><span class="muted">${p.pos} · ${p.ovr} overall · age ${p.age} · speed ${p.spd}</span></div>
  <p>${devTag(p)} potential${p.age<=25?', projected to reach about '+p.pot+' overall':''}. ${p.dev==='F'?'Improves fastest and is cheaper to upgrade.':p.dev==='E'?'Improves quickly each offseason.':p.dev==='S'?'Improves steadily each offseason.':'Improves slowly.'}</p>
  ${p.xf?`<p><span class="xf">X</span> <b>${xfName(p)}.</b> ${xfDesc(p)}</p>`:`<p class="muted">Earns an X-Factor at ${XF_OVR} overall (one of ${XFS[p.pos].map(x=>x[1]).join(', ')}).</p>`}
  ${p.aw&&p.aw.length?`<p><b>Awards:</b> ${p.aw.slice(-6).map(esc).join(' · ')}</p>`:''}${p.cap?'<p><span class="tag cap">C</span> Team captain: plays 2 points above his rating.</p>':''}${p.inj?'<p><span class="tag inj">Injured</span> Out '+p.inj+(p.inj===1?' more week. A healthy backup starts in his place.':' more weeks. A healthy backup starts in his place.')+'</p>':''}
  ${careerTable(p)}
  <div class="row"><label for="edName">Name</label><input id="edName" value="${esc(p.n)}" maxlength="22" autocomplete="off"><label for="edNum">Number</label><input id="edNum" type="number" min="0" max="99" value="${p.num}" inputmode="numeric"><button class="btn sm" data-a="edSave">Save</button></div>
  <div class="row"><button class="btn sm" data-a="edUp"${c&&S.tp>=c?'':' disabled'}>${c?'Upgrade +1 overall ('+c+' point'+(c>1?'s':'')+')':'Maxed out'}</button><button class="btn ghost sm" data-a="edCap">${p.cap?'Remove captain':'Make captain'}</button>${['RB','WR','CB','S'].includes(p.pos)?`<button class="btn ghost sm" data-a="edKr"${p.kr?' disabled':''}>${p.kr?'Kick returner':'Set as kick returner'}</button>`:''}<button class="btn ghost sm" data-a="edRel">Release</button><button class="btn ghost sm" data-a="edClose">Close</button>${UI.edMsg?`<span class="${UI.edOk?'good':'bad'}">${esc(UI.edMsg)}</span>`:''}</div></section>`;}
function vRoster(){const U=S.teams[S.user],fa=UI.rv==='fa';
  let h='<div class="wrap">'+(fa?'':editor(U))+`<div class="row"><button class="btn ghost sm${fa?'':' sel'}" data-a="rv" data-v="team">My team</button><button class="btn ghost sm${fa?' sel':''}" data-a="rv" data-v="fa">Free agents (${S.fa.length})</button><span class="muted">${U.roster.length} of ${ROSTER_MAX} roster spots used</span></div>`;
  h+='<div class="row">'+[['ALL','Everyone'],['OFF','Offense'],['DEF','Defense'],['K','Kicker']].map(f=>`<button class="btn ghost sm${UI.rf===f[0]?' sel':''}" data-a="rf" data-f="${f[0]}">${f[1]}</button>`).join('')+`<span class="muted">${fa?'Signing costs training points. You have '+S.tp+'.':'Tap a player to edit, upgrade, release, name a captain (up to 4) or choose your kick returner.'}</span>${fa&&UI.faMsg?`<span class="${UI.faOk?'good':'bad'}">${esc(UI.faMsg)}</span>`:''}</div>`;
  if(fa){const list=S.fa.filter(p=>FILT[UI.rf].includes(p.pos)).sort((a,b)=>b.ovr-a.ovr).slice(0,60);
    h+='<div class="card scroll"><table class="tbl"><thead><tr><th></th><th class="l">Free agent</th><th>Pos</th><th>Ovr</th><th class="l">Potential</th><th>Age</th><th>Spd</th><th>Your starter</th></tr></thead><tbody>';
    for(const p of list){const c=signCost(p);h+=`<tr><td class="l"><button class="btn sm" data-a="sign" data-id="${p.id}"${S.tp>=c&&U.roster.length<ROSTER_MAX?'':' disabled'}>Sign · ${c}</button></td><td class="l">${esc(p.n)}${xfTag(p)}</td><td>${p.pos}</td><td class="ovr">${p.ovr}</td><td class="l">${devTag(p)}</td><td>${p.age}</td><td>${p.spd}</td><td>${lowestStarter(U,p.pos,[])}</td></tr>`;}
    if(!list.length)h+='<tr><td class="l" colspan="8">No free agents at this position.</td></tr>';
    h+='</tbody></table></div>';}
  else{const list=U.roster.filter(p=>FILT[UI.rf].includes(p.pos)).sort((a,b)=>posRank(a)-posRank(b));
    h+='<div class="card scroll"><table class="tbl"><thead><tr><th>No.</th><th class="l">Player</th><th>Pos</th><th>Age</th><th>Ovr</th><th class="l">Potential</th><th>Spd</th><th>Trade value</th></tr></thead><tbody>';
    for(const p of list)h+=`<tr class="pl${isStarter(U,p)?' st':''}${UI.sel===p.id?' cur':''}" data-a="sel" data-id="${p.id}" tabindex="0"><td>${p.num}</td><td class="l">${esc(p.n)}${xfTag(p)}${p.cap?' <span class="tag cap">C</span>':''}${p.kr?' <span class="tag">KR</span>':''}${p.inj?' <span class="tag inj">Out '+p.inj+' wk</span>':''}${isStarter(U,p)?' <span class="tag">Starter</span>':''}</td><td>${p.pos}</td><td>${p.age}</td><td class="ovr">${p.ovr}</td><td class="l">${devTag(p)}</td><td>${p.spd}</td><td>${tradeValue(p).toFixed(1)}</td></tr>`;
    h+='</tbody></table></div>';}
  $('#view').innerHTML=h+'</div>';}

// ----- trades -----
function trRow(p,on,act,T){return `<button class="prow${on?' on':''}" data-a="${act}" data-id="${p.id}" aria-pressed="${on}"><span class="pos">${p.pos}</span><span class="nm">${esc(p.n)}${xfTag(p)}${isStarter(T,p)?' <span class="tag">S</span>':''}</span><span class="muted">${p.age}y</span><span class="ovr">${p.ovr}</span><span class="muted">${tradeValue(p).toFixed(1)}</span></button>`;}
function pkRow(k,on,act){return `<button class="prow pk${on?' on':''}" data-a="${act}" data-id="${k.id}" aria-pressed="${on}"><span class="pos">PK</span><span class="nm">${pickName(k)}</span><span class="muted"></span><span class="ovr">R${k.rd}</span><span class="muted">${pickValue(k).toFixed(1)}</span></button>`;}
function vTrade(){const U=S.teams[S.user],tr=UI.tr;if(tr.team<0||tr.team===S.user)tr.team=S.teams.find(t=>t.id!==S.user).id;const T=S.teams[tr.team];
  tr.give=tr.give.filter(id=>byId(U,id));tr.get=tr.get.filter(id=>byId(T,id));tr.gk=tr.gk.filter(id=>pkById(id)&&pkById(id).own===U.id);tr.tk=tr.tk.filter(id=>pkById(id)&&pkById(id).own===T.id);
  const give=tr.give.map(id=>byId(U,id)),get=tr.get.map(id=>byId(T,id)),gk=tr.gk.map(pkById),tk=tr.tk.map(pkById),open=tradesOpen(),nG=give.length+gk.length,nT=get.length+tk.length;
  let h='<div class="wrap">';
  if(!open)h+='<section class="card"><p class="eyebrow">Trading is closed</p><p class="muted">'+(S.phase==='draft'?'Trades reopen when the draft ends.':'The deadline is after week '+TRADE_DEADLINE+'. Trades reopen in the offseason.')+'</p></section>';
  h+=`<div class="row"><label for="trTeam">Trade with</label><select id="trTeam">${S.teams.filter(t=>t.id!==S.user).map(t=>`<option value="${t.id}"${t.id===T.id?' selected':''}>${t.name} (${t.w}-${t.l})</option>`).join('')}</select><span class="muted">Pick up to 5 players or draft picks on each side. The last column is trade value. Picks always run two drafts ahead.</span></div>`;
  const srt=(a,b)=>posRank(a)-posRank(b);
  h+=`<div class="tr-cols"><section class="card"><h3>You send <span class="muted">${nG}/5</span></h3><div class="plist">${teamPicks(U.id).map(k=>pkRow(k,tr.gk.includes(k.id),'trGk')).join('')}${U.roster.slice().sort(srt).map(p=>trRow(p,tr.give.includes(p.id),'trGive',U)).join('')}</div></section><section class="card"><h3>${T.name} send <span class="muted">${nT}/5</span></h3><div class="plist">${teamPicks(T.id).map(k=>pkRow(k,tr.tk.includes(k.id),'trTk')).join('')}${T.roster.slice().sort(srt).map(p=>trRow(p,tr.get.includes(p.id),'trGet',T)).join('')}</div></section></div>`;
  let sum='<p class="muted">Select players or picks to see what they think.</p>';
  if(nG&&nT){const ev=aiEval(T,give,get,gk,tk),ok=ev.ratio>=1.03;
    sum=`<div class="row"><span>${T.name} interest</span><div class="meter${ok?' ok':''}"><i style="width:${Math.round(clamp(ev.ratio/1.03,0.04,1)*100)}%"></i></div><b>${ok?'They would say yes':ev.ratio>0.8?'Close':'Not enough'}</b></div>`;}
  h+=`<section class="card tr-sum">${sum}<div class="row"><button class="btn" data-a="propose"${open&&nG&&nT?'':' disabled'}>Propose trade</button><button class="btn ghost sm" data-a="trClear">Clear</button>${tr.msg?`<span class="${tr.ok?'good':'bad'}">${esc(tr.msg)}</span>`:''}</div></section>`;
  const v=$('#view'),sc=[...v.querySelectorAll('.plist')].map(e=>e.scrollTop),vs=v.scrollTop;v.innerHTML=h+'</div>';
  [...v.querySelectorAll('.plist')].forEach((e,i)=>{e.scrollTop=sc[i]||0;});v.scrollTop=vs;}

// ----- draft room -----
function vDraft(){const D=S.draft,pk=curPick(),T=S.teams[pk.own],mine=pk.own===S.user,U=S.teams[S.user];
  const left=D.order.slice(D.i).map(pkById).filter(k=>k.own===S.user);
  let h=`<div class="wrap"><section class="card hero"><p class="eyebrow">${D.yr} draft · Round ${pk.rd} · Pick ${D.i+1} of ${D.order.length}</p><h2>${mine?'You are on the clock':sw(T)+' '+T.name+' are on the clock'}</h2>
  <p class="muted">${left.length?'Your picks left: '+left.map(k=>'Round '+k.rd+(k.orig!==k.own?' (from '+S.teams[k.orig].name+')':'')).join(', ')+'.':'You have no picks left in this draft.'}</p>
  <div class="row">${mine?'<button class="btn ghost" data-a="draftAuto">Pick the best fit for me</button>':`<button class="btn" data-a="draftSim">${left.length?'Sim to my next pick':'Sim the rest of the draft'}</button>`}</div></section>`;
  if(mine){const F=['ALL',...POS_ORDER],pool=D.pool.filter(p=>UI.dpos==='ALL'||p.pos===UI.dpos).slice(0,40);
    h+='<div class="row">'+F.map(f=>`<button class="btn ghost sm${UI.dpos===f?' sel':''}" data-a="dpos" data-f="${f}">${f==='ALL'?'All':f}</button>`).join('')+'</div>';
    h+='<div class="card scroll"><table class="tbl"><thead><tr><th></th><th class="l">Prospect</th><th>Pos</th><th>Ovr</th><th class="l">Potential</th><th>Age</th><th>Spd</th><th>You have</th></tr></thead><tbody>';
    for(const p of pool){const have=U.roster.filter(x=>x.pos===p.pos);h+=`<tr><td class="l"><button class="btn sm" data-a="draftPick" data-id="${p.id}">Draft</button></td><td class="l">${esc(p.n)}</td><td>${p.pos}</td><td class="ovr">${p.ovr}</td><td class="l">${devTag(p)}</td><td>${p.age}</td><td>${p.spd}</td><td>${have.length} (best ${have.reduce((m,x)=>Math.max(m,x.ovr),0)})</td></tr>`;}
    h+='</tbody></table></div>';}
  if(D.log.length)h+='<section class="card"><h3>Latest picks</h3><ul class="news">'+D.log.slice(0,10).map(l=>`<li>${l.no}. ${sw(S.teams[l.team])} ${S.teams[l.team].name}: <b>${l.pos} ${esc(l.n)}</b> <span class="muted">${l.ovr} overall</span></li>`).join('')+'</ul></section>';
  $('#view').innerHTML=h+'</div>';}

// ----- league -----
function vLeague(){let h='<div class="wrap">';const U=S.teams[S.user];h+=leadersCard();
  if(S.po){h+='<section class="card"><h3>Playoffs</h3>';const line=g=>{const H=S.teams[g.h],A=S.teams[g.a];return `<li>${sw(A)} ${A.name} ${g.as==null?'':g.as} at ${sw(H)} ${H.name} ${g.hs==null?'':g.hs}</li>`;};
    if(S.po.games.length)h+=`<p class="eyebrow">${roundName()}</p><ul class="news">${S.po.games.map(line).join('')}</ul>`;
    for(const r of S.po.log.slice().reverse())h+=`<p class="eyebrow">${r.name}</p><ul class="news">${r.games.map(line).join('')}</ul>`;
    h+='</section>';}
  if(S.phase==='regular'){h+='<section class="card"><h3>Playoff picture</h3><p class="muted">Each conference sends its four division winners (seeds 1 to 4), then the three best remaining records as wild cards (seeds 5 to 7). The top seed gets a bye.</p><div class="tr-cols">';
    for(const c of ['A','N']){const s=seedsFor(c),row=(T,i,lab,cls)=>`<tr class="${T.id===S.user?'me':''} ${cls}"><td>${i}</td><td class="l">${sw(T)} ${T.name}</td><td>${T.w}-${T.l}</td><td class="l muted">${lab}</td></tr>`;
      h+=`<div class="scroll"><table class="tbl"><thead><tr><th>Seed</th><th class="l">${CONF[c]}</th><th>Rec</th><th class="l">In as</th></tr></thead><tbody>`+s.div.map((T,i)=>row(T,i+1,T.div+' winner','')).join('')+s.wc.map((T,i)=>row(T,i+5,'Wild card','')).join('')+s.hunt.map(T=>row(T,'','In the hunt','out')).join('')+'</tbody></table></div>';}
    h+='</div></section>';}
  if(S.phase!=='offseason'&&S.phase!=='preseason')h+=awardsCard();
  for(const c of ['A','N']){h+=`<section class="card scroll"><h3>${CONF[c]} conference</h3><table class="tbl"><thead><tr><th class="l">Team</th><th>W</th><th>L</th><th>PF</th><th>PA</th><th>Ovr</th></tr></thead><tbody>`;
    for(const d of DIVS){h+=`<tr class="div"><td class="l" colspan="6">${d}</td></tr>`;
      for(const T of S.teams.filter(t=>t.conf===c&&t.div===d).sort(cmpTeams))h+=`<tr class="${T.id===S.user?'me':''}"><td class="l">${sw(T)} ${T.name}</td><td>${T.w}</td><td>${T.l}</td><td>${T.pf}</td><td>${T.pa}</td><td>${ratings(T).ovr}</td></tr>`;}
    h+='</tbody></table></section>';}
  h+=historyCards();
  h+='<section class="card"><h3>Your schedule</h3><p class="muted">Seventeen games in eighteen weeks: each division rival twice, plus one bye.</p><ul class="news">';
  S.schedule.forEach((wk,i)=>{const g=wk.find(x=>x.h===S.user||x.a===S.user);if(!g){h+=`<li>Week ${i+1}: <span class="muted">Bye</span></li>`;return;}const home=g.h===S.user,opp=S.teams[home?g.a:g.h];
    const res=g.hs==null?'':(()=>{const us=home?g.hs:g.as,th=home?g.as:g.hs;return ` <b class="${us>th?'good':'bad'}">${us>th?'W':'L'} ${us}-${th}</b>`;})();
    h+=`<li>Week ${i+1}: ${home?'vs':'at'} ${sw(opp)} ${opp.name}${opp.conf===U.conf&&opp.div===U.div?' <span class="tag">Division</span>':''}${res}</li>`;});
  $('#view').innerHTML=h+'</ul></section></div>';}

// ===== in-game panel =====
function playSvg(pl){const F=FORMS[pl.f],y=z=>22-clamp(z,-7,22),roles=['WR1','WR3','TE','RB','WR2','QB'];
  let s='<svg viewBox="-27 -1 54 31" aria-hidden="true"><line x1="-27" x2="27" y1="22" y2="22" class="pl-los"/>';
  for(const x of [-2.9,-1.45,0,1.45,2.9])s+=`<rect x="${x-0.55}" y="${y(-0.7)-0.55}" width="1.1" height="1.1" class="pl-ol"/>`;
  if(pl.t==='pass'){const el=Object.keys(pl.r).filter(k=>pl.r[k]).sort((a,b)=>F[a][0]-F[b][0]);
    for(const k of roles){const f=F[k],i=el.indexOf(k);if(i<0){s+=`<circle cx="${f[0]}" cy="${y(f[1])}" r="1.2" class="pl-dot"/>`;continue;}
      const sg=f[0]<-0.5?-1:1;let pts=f[0]+','+y(f[1]);for(const w of RT[pl.r[k]])pts+=' '+clamp(f[0]+w[0]*sg,-26,26)+','+y(f[1]+w[1]);
      s+=`<polyline points="${pts}" class="pl-rt" style="stroke:${RCOL[i%5]}"/><circle cx="${f[0]}" cy="${y(f[1])}" r="1.5" fill="${RCOL[i%5]}"/>`;}}
  else{const c=pl.sneak?F.QB:F.RB,hx=pl.aim;for(const k of roles){const f=F[k];s+=`<circle cx="${f[0]}" cy="${y(f[1])}" r="1.2" class="pl-dot"/>`;}
    s+=`<polyline points="${c[0]},${y(c[1])} ${pl.sneak?hx+','+y(5):hx*0.4+','+y(-2.2)+' '+hx+','+y(1.5)+' '+(hx+(hx>5?2:hx<-5?-2:0))+','+y(9)}" class="pl-rt" style="stroke:${RCOL[2]}"/>`;}
  return s+'</svg>';}
const tmx=(g,team)=>{team=team||'U';const n=g.to?g.to[team]:0;return !g.ko&&!g.conv&&!g.drill&&n>0?`<button class="btn ghost sm" data-a="timeout" data-v="${team}">Timeout (${n})${coarse?'':' <span class="kbd">'+(g.two&&team==='A'?'P':'T')+'</span>'}</button>`:'';};
const kn=(team,i)=>gm&&gm.two&&team==='A'?(i+5)%10:i;
const pl=team=>gm&&gm.two?'Player '+(team==='U'?1:2)+' · '+esc((team==='U'?gm.U:gm.O).name):'';
function renderPanel(){const p=$('#panel'),g=gm;if(!g){p.innerHTML='';return;}let h='';const uo=g.poss==='U',kb=t=>coarse?'':` <span class="kbd">${t}</span>`,ph=g.phase,off=g.two?g.poss:'U',def=off==='U'?'A':'U',k2=t=>g.two&&g.poss==='A'?({Space:'Enter',T:'P',R:'R',K:'K',H:'H'}[t]||t):t;
  if(g.pro&&!g.two){const x=proPanel(g,kb);if(x!=null){p.className=ph==='live'?'live':'';p.innerHTML=x;return;}}
  if(ph==='huddle'){const offPick=g.two?g.hs==='O':uo,L=listed(),sit=SIT_NAME[situation()],tabs=offPick?GROUPS:[['S','Coach picks'],['Q','All calls']];
    const head=g.two?`<b>${offPick?pl(g.poss)+': pick a play':pl(def)+': pick a defense'}</b> · `:'';
    h='<div class="pbtabs">'+tabs.map(t=>`<button class="${g.tab===t[0]?'on':''}" data-a="pbtab" data-t="${t[0]}">${t[1]}</button>`).join('')+`<span class="muted">${head}${!offPick&&!g.two?esc(g.O.name)+' have the ball · ':''}${sit}${g.conv?' · Two-point try':''}${g.two?(offPick?' · '+pl(def)+', look away':' · '+pl(g.poss)+', look away'):''}</span></div>`;
    const keyN=i=>g.two&&(offPick?g.poss:def)==='A'?(i+6)%10:i+1;
    if(offPick){if(g.tab==='T'&&!L.length)h+='<p class="muted">Fake punts and fake field goals show up here on fourth down.</p>';
      h+='<div class="plays">'+L.map((pl2,i)=>`<button class="play" data-a="call" data-i="${i}">${g.two&&g.hs!=='O'?'':playSvg(pl2)}<b><span class="kbd">${keyN(i)}</span>${pl2.n}</b><small>${FORMS[pl2.f].n} · ${pl2.d}</small></button>`).join('')+'</div>';
      const d=fgDist(),fourth=g.down===4&&!g.conv,ex=g.conv?'':(d<=57?`<button class="btn ghost sm" data-a="fg">Kick field goal (${d} yards)</button>`:'')+(fourth&&g.q!==5?'<button class="btn ghost sm" data-a="punt">Punt</button><button class="btn ghost sm" data-a="fake" data-v="punt">Fake punt</button>':'')+(fourth&&d<=57?'<button class="btn ghost sm" data-a="fake" data-v="fg">Fake field goal</button>':'')+(canKneel()?'<button class="btn ghost sm" data-a="kneel">Kneel</button>':'')+(g.run&&g.down<4&&!g.conv?`<button class="btn ghost sm" data-a="spike">Spike${kb(k2('K'))}</button>`:'')+(g.lastPlay&&!g.conv?`<button class="btn ghost sm" data-a="same">Same play${kb('R')}</button>`:'')+(g.drill?'':`<button class="btn ghost sm${g.hurry?' sel':''}" data-a="hurry">Hurry-up: ${g.hurry?'on':'off'}${kb('H')}</button>`)+tmx(g,off)+(g.drill?'':'<button class="btn ghost sm" data-a="simDrive">Sim drive</button>');
      if(ex)h=h.replace('<div class="plays">','<div class="row sp">'+ex+'</div><div class="plays">');if(!g.two)h+='<p class="muted tip">Tip: turn your phone sideways for a bigger field.</p>';}
    else h+='<div class="row sp">'+tmx(g,def)+(g.drill||g.two?'':'<button class="btn ghost sm" data-a="simDrive">Sim drive</button>')+'</div><div class="plays dcalls">'+L.map((ci,i)=>`<button class="play" data-a="dcall" data-i="${i}"><b><span class="kbd">${keyN(i)}</span>${DCALLS[ci].n}</b><small>${DCALLS[ci].d}</small></button>`).join('')+'</div>';}
  else if(ph==='kometer'){const kt=g.kom.kicker;h=`<div class="row"><b class="res">${g.two?pl(kt)+' · ':''}Kickoff</b><div class="kick"><span class="zone" style="left:92%;width:16%"></span><span class="mk" id="kmk"></span></div><button class="btn" data-a="koHit">Kick${kb(g.two&&kt==='A'?'Enter':'Space')}</button></div><p class="muted">Stop the marker at the far right, in the green, for the longest kick. Too early and it's short, which gives the returner great field position.</p>`;}
  else if(ph==='kochoice')h=`<div class="row"><b class="res">Your kickoff</b><button class="btn" data-a="koDeep"><span class="kbd">1</span>Kick deep</button><button class="btn ghost" data-a="koOnside"><span class="kbd">2</span>Onside kick</button></div><p class="muted">You're behind late. An onside kick is a short kick your team can try to recover, but it usually fails and hands them great field position.</p>`;
  else if(ph==='presnap'&&g.ko){const kt=uo?'A':'U';if(g.two)h=`<div class="row"><button class="btn" data-a="snap">${g.onside?'Onside kick':'Kick off'}${kb(kt==='A'?'Enter':'Space')}</button>${g.onside?'':'<button class="btn ghost sm" data-a="onside">Onside kick instead</button>'}<span class="muted">${pl(kt)} kicks off. ${pl(g.poss)} returns with #${g.by.RET.num}.</span></div>`;
    else h=uo?`<div class="row"><button class="btn" data-a="snap">Ready${kb('Space')}</button><span class="muted">${esc(g.O.name)} ${g.onside?'line up for an onside kick! Get to the ball.':'kick off. Catch it with #'+g.by.RET.num+' '+esc(g.by.RET.rp.n)+' and follow your blockers.'}</span></div>`:`<div class="row"><button class="btn" data-a="snap">${g.onside?'Onside kick':'Kick off'}${kb('Space')}</button>${g.onside?'':'<button class="btn ghost sm" data-a="onside">Onside kick</button>'}<button class="btn ghost sm" data-a="sw">Switch player${kb('Q')}</button><span class="muted">${g.onside?'A short kick: it has to go 10 yards before your team can recover it.':'You kick off. Steer the player under the blue marker to the returner.'}</span></div>`;}
  else if(ph==='presnap'&&(uo||g.two)){if(g.aud)h=audPanel(g);
    else h=`<div class="row"><button class="btn" data-a="snap">Snap${kb(k2('Space'))}</button>${g.two?'':'<button class="btn ghost sm" data-a="change">Change play</button>'}<button class="btn ghost sm" data-a="aud" data-v="list">Audible</button>${g.play.t==='pass'?'<button class="btn ghost sm" data-a="aud" data-v="hot">Hot route</button>':''}${g.run&&g.down<4&&!g.conv?`<button class="btn ghost sm" data-a="spike">Spike</button>`:''}${tmx(g,off)}<span class="muted">${g.two?pl(off)+' · ':''}<b>${g.play.n}</b> · ${g.play.t==='pass'?'Throw: '+(coarse?'tap a receiver':g.two&&off==='A'?'press 6 to 0':'press his number or click him')+'.'+(g.play.hook?' After the catch, pitch it back with '+(g.two?(off==='A'?';':'G'):'L')+'.':''):g.play.sneak?'You carry it with '+(g.play.fake?'the holder':'the quarterback')+'.':g.play.rev?'The receiver takes the reverse. Follow the orange path.':'Follow the orange path. You take over at the handoff.'}${g.two?' · '+pl(def)+' on defense: switch with '+(def==='A'?'.':'Q')+'.':''}</span></div>`;}
  else if(ph==='presnap')h=`<div class="row"><button class="btn" data-a="snap">Ready${kb('Space')}</button><button class="btn ghost sm" data-a="sw">Switch player${kb('Q')}</button>${tmx(g)}<span class="muted">You control #${g.ctl.num} ${esc(g.ctl.rp.n)} (${g.ctl.rp.pos}), under the blue marker. Call: ${DCALLS[g.defCall].n}.</span></div>`;
  else if(ph==='live'&&g.loose)h=coarse?`<div class="pad"><span class="muted">Loose ball! Drag to steer your player onto it.</span></div>`:`<div class="row"><b class="res">Loose ball!</b><span class="muted">Steer the player under the marker onto the ball${g.two?' (both players)':''}.</span></div>`;
  else if(ph==='live'&&g.two)h=`<div class="row"><span class="muted">${pl(off)}: move, ${off==='U'?'Space juke, E spin, G pitch, 1-5 throw':'Enter juke, / spin, ; pitch, 6-0 throw'}. ${pl(def)}: move, ${def==='U'?'Space dive, Q switch':'Enter dive, . switch'}.</span></div>`;
  else if(ph==='live'&&(g.ret?!!(g.carrier&&g.carrier.team==='U'):uo))h=coarse?`<div class="pad"><span class="muted">${g.ret?'Run it back! Drag to steer.':'Drag here or on the field to move.'+(g.play.t==='pass'?' Tap a receiver to throw.':'')}</span><span class="row"><button class="btn ghost" data-a="lateral">Pitch</button><button class="btn ghost" data-a="spin">Spin</button><button class="btn" data-a="juke">Juke</button></span></div>`:`<div class="row"><span class="muted">${g.ret?'Run it back! ':''}Move: WASD or arrows. ${g.play.t==='pass'&&!g.ret?'Throw: press a receiver\'s number or click him. ':''}Juke: Space. Spin: E or F.${g.ret?'':' Pitch it back: L.'}</span></div>`;
  else if(ph==='live')h=coarse?`<div class="pad"><span class="muted">Drag to move your defender.</span><span class="row"><button class="btn ghost" data-a="sw">Switch</button><button class="btn" data-a="dive">Tackle</button></span></div>`:`<div class="row"><span class="muted">Move: WASD or arrows. Dive tackle or swat a pass: Space. Switch to the defender nearest the ball: Q.</span></div>`;
  else if(ph==='dead'&&g.cele&&!g.cele.picked&&(!g.two||g.cele.e.team==='U'))h=`<div class="row"><b class="res">${esc(g.msg)}</b><span class="muted">Celebrate:</span>${CELES.map((c,i)=>`<button class="btn sm" data-a="cele" data-i="${i}"><span class="kbd">${i+1}</span>${c}</button>`).join('')}</div>`;
  else if(ph==='dead')h=`<div class="row"><b class="res">${esc(g.msg)}</b>${g.rec&&g.rec.frames.length>5?`<button class="btn ghost sm" data-a="replay">Replay${kb('R')}</button>`:''}</div>`;
  else if(ph==='replay'){const R=g.rp,r=R.list[R.i];h=`<div class="row"><b class="res">${R.list.length>1?'Highlight '+(R.i+1)+' of '+R.list.length:'Instant replay'}</b><span class="muted">${esc(r.title||'')}</span></div><div class="row"><button class="btn sm" data-a="rpPause">${R.paused?'Play':'Pause'}${kb('Space')}</button><button class="btn ghost sm" data-a="rpAng">Camera: ${ANGLES[R.ang]}${kb('C')}</button><button class="btn ghost sm${R.spd<1?' sel':''}" data-a="rpSlow">Slow motion${kb('S')}</button><button class="btn ghost sm" data-a="rpRestart">Restart${kb('R')}</button>${R.list.length>1&&R.i<R.list.length-1?`<button class="btn ghost sm" data-a="rpNext">Next${kb('N')}</button>`:''}<button class="btn" data-a="rpExit">${R.from==='card'?'Done':'Back to the game'}${kb('Esc')}</button></div>`;}
  else if(ph==='toss'){const T=g.toss,W=T.win==='U'?g.U:g.O;
    if(T.step==='call')h=`<div class="row"><b class="res">${T.ot?'Overtime coin toss':'Coin toss'}</b><span class="muted">${g.two?pl('A')+' (visitors), call it:':'You\'re the visitors. Call it in the air:'}</span><button class="btn" data-a="toss" data-v="1"><span class="kbd">${kn('A',1)}</span>Heads</button><button class="btn" data-a="toss" data-v="0"><span class="kbd">${kn('A',2)}</span>Tails</button></div>`;
    else if(T.step==='choose')h=`<div class="row"><b class="res">${esc(T.text)} ${g.two?esc(W.name)+' win the toss.':'You win the toss.'}</b></div><div class="row"><button class="btn" data-a="tossPick" data-v="1"><span class="kbd">${kn(T.win,1)}</span>${T.ot?'Take the ball':'Receive the kickoff'}</button><button class="btn ghost" data-a="tossPick" data-v="0"><span class="kbd">${kn(T.win,2)}</span>${T.ot?'Start on defense':'Kick off'}</button></div>`;
    else h=`<div class="row"><b class="res">${esc(T.text)} ${esc(g.O.name)} win the toss and ${T.ot?'take the ball':'will receive'}.</b><button class="btn" data-a="tossPick" data-v="0">Continue${kb('Space')}</button></div>`;}
  else if(ph==='intro')h=`<div class="row"><button class="btn" data-a="introSkip">Start the game${kb('Space')}</button><span class="muted">${esc(stadOf(g.home)[4])}${S.talk>=2?' Turn your sound on to hear the booth.':''}</span></div>`;
  else if(ph==='flag'){const f=g.pend,a=penCalc(f.pen,f.snap.pos,f.snap.down,f.snap.toGo),FT=f.pen.off?(uo?g.U:g.O):(uo?g.O:g.U),BT=FT===g.U?g.O:g.U;
    h=`<div class="row"><b class="res">Flag: ${f.pen.n} on ${esc(FT.name)}</b>${g.two?'<span class="muted">'+esc(BT.name)+' decide</span>':''}</div><div class="row"><button class="btn" data-a="flag" data-v="1"><span class="kbd">${g.two&&BT===g.O?6:1}</span>Accept · ${downText(a.down,a.toGo,a.pos)}</button><button class="btn ghost" data-a="flag" data-v="0"><span class="kbd">${g.two&&BT===g.O?7:2}</span>Decline · ${esc(g.msg.split(' · Flag')[0])}</button></div><p class="muted">Accept to take the penalty yards and replay the down. Decline to keep the result of the play.</p>`;}
  else if(ph==='pat')h=`<div class="row"><b class="res">${g.two?pl(g.poss)+' · ':''}After the touchdown</b><button class="btn" data-a="pat" data-two="0"><span class="kbd">${kn(g.poss,1)}</span>Kick the extra point</button><button class="btn ghost" data-a="pat" data-two="1"><span class="kbd">${kn(g.poss,2)}</span>Go for two</button></div><p class="muted">The kick is worth 1 point. A two-point try is one play from the 2-yard line.</p>`;
  else if(ph==='kick'){const K=g.kick,b=K.bias||0,w=g.wx&&g.wx.wind||0;h=`<div class="row"><b class="res">${K.xp?'Extra point':K.dist+'-yard field goal'}</b><div class="kick"><span class="zone" style="width:${Math.round(K.tol*100)}%;left:${50+b*50}%"></span><span class="mk" id="kmk"></span></div><button class="btn" data-a="kick">Kick${kb(g.two&&K.side==='A'?'Enter':'Space')}</button></div><p class="muted">Stop the marker inside the green zone.${w>=4?' Wind '+w+' mph '+((g.wx.wdir>0)!==FLIP?'left to right':'right to left')+': the zone is shifted.':''}${g.wx&&g.wx.sky==='snow'?' Snow makes the zone smaller.':''}</p>`;}
  else if(ph==='kanim')h=`<div class="row"><b class="res">${g.kanim.xp?'Extra point':g.kanim.dist+'-yard field goal'} · ${g.kanim.side==='U'?esc(g.U.name):esc(g.O.name)}</b></div>`;
  else if(g.card)h=`<div class="cardp"><h3>${esc(g.card.title)}</h3>${g.card.lines.map(l=>`<p>${esc(l)}</p>`).join('')}<div class="row"><button class="btn" data-a="cont">${g.card.btn}</button>${g.card.final&&g.hls&&g.hls.length?`<button class="btn ghost" data-a="hl">Watch highlights (${g.hls.length})</button>`:''}</div></div>`;
  p.className=ph==='live'?'live':'';p.innerHTML=h;}

// ===== actions =====
function togAsset(arr,id){const tr=UI.tr,i=arr.indexOf(id),mine=arr===tr.give||arr===tr.gk,n=mine?tr.give.length+tr.gk.length:tr.get.length+tr.tk.length;if(i>=0)arr.splice(i,1);else if(n<5)arr.push(id);tr.msg='';render();}
const ACT={
  pick(d){UI.two=null;S.user=+d.id;UI.tab='home';S.news=['Welcome to '+S.teams[S.user].name+'. Trades are open until week '+TRADE_DEADLINE+'. You start with '+S.tp+' training points.'];save();render();},
  tab(d){UI.tab=d.t;UI.confirmNew=false;UI.tr.msg='';UI.edMsg='';UI.faMsg='';render();$('#view').scrollTop=0;},
  play(){if(onRoad()){roadPlay();return;}openSetup();render();$('#view').scrollTop=0;},
  setupBack(){UI.setup=null;render();},
  uni(d){if(!UI.setup)return;UI.setup[d.s==='U'?'uU':'uO']=d.k;render();},
  kickoff(){const su=UI.setup;if(!su)return;UI.setup=null;const p=isPro()?proP():null;startGame(S.teams[su.opp],su.home,su.uU,su.uO,p?{pro:{id:p.id,pos:p.pos,n:p.n}}:undefined);},
  sim(){UI.setup=null;if(onRoad())roadSim();else if(isPro())proSimGame();else completeStep(false);render();},
  roadAll(){let g=0;while(onRoad()&&roadMatch()&&g++<20)roadSim();render();$('#view').scrollTop=0;},
  roadNext(){roadNext();render();$('#view').scrollTop=0;},roadDeclare(){roadDeclare();render();$('#view').scrollTop=0;},
  roadCommit(d){roadCommit(+d.k);UI.tab='home';render();$('#view').scrollTop=0;},roadDraft(){roadDraft();render();$('#view').scrollTop=0;},roadNFL(){roadToNFL();UI.tab='home';render();$('#view').scrollTop=0;},
  proXF(d){const e=proXF(d.k);UI.proMsg=e||'X-Factor equipped: '+xfName(proP())+'.';UI.proOk=!e;render();},
  pnStart(d){pnRead();UI.pn.start=d.k;render();},
  startDraft(){startDraft();UI.dpos='ALL';render();$('#view').scrollTop=0;},
  draftSim(){simDraftToUser();render();$('#view').scrollTop=0;},
  draftAuto(){if(S.phase==='draft'&&curPick().own===S.user)makePick(aiPick(S.teams[S.user]));render();},
  draftPick(d){if(S.phase!=='draft'||curPick().own!==S.user)return;const p=S.draft.pool.find(x=>x.id===+d.id);if(p)makePick(p);render();$('#view').scrollTop=0;},
  dpos(d){UI.dpos=d.f;render();},
  newSeason(){if(newSeason())render();},
  rf(d){UI.rf=d.f;render();},
  rv(d){UI.rv=d.v;UI.faMsg='';render();},
  sign(d){const p=S.fa.find(x=>x.id===+d.id);if(!p)return;const e=signFA(p);UI.faMsg=e||'Signed '+p.n+'.';UI.faOk=!e;render();},
  sel(d){UI.sel=+d.id;UI.edMsg='';render();$('#view').scrollTop=0;},
  edClose(){UI.sel=null;UI.edMsg='';render();},
  edSave(){const p=byId(S.teams[S.user],UI.sel);if(!p)return;const e=editPlayer(p,$('#edName').value,$('#edNum').value);UI.edMsg=e||'Saved.';UI.edOk=!e;render();},
  edUp(){const p=byId(S.teams[S.user],UI.sel);if(!p)return;const e=upgradePlayer(p);UI.edMsg=e||'Upgraded to '+p.ovr+' overall.';UI.edOk=!e;render();},
  edRel(){const p=byId(S.teams[S.user],UI.sel);if(!p)return;if(UI.relId!==p.id){UI.relId=p.id;UI.edMsg='Tap Release again to let him go to free agency.';UI.edOk=false;render();return;}
    UI.relId=null;const e=releasePlayer(p);if(e){UI.edMsg=e;UI.edOk=false;}else{UI.sel=null;UI.edMsg='';}render();},
  trGive(d){togAsset(UI.tr.give,+d.id);},trGet(d){togAsset(UI.tr.get,+d.id);},trGk(d){togAsset(UI.tr.gk,+d.id);},trTk(d){togAsset(UI.tr.tk,+d.id);},
  trClear(){const tr=UI.tr;tr.give=[];tr.get=[];tr.gk=[];tr.tk=[];tr.msg='';render();},
  propose(){const tr=UI.tr,U=S.teams[S.user],T=S.teams[tr.team];const r=proposeTrade(T,tr.give.map(id=>byId(U,id)),tr.get.map(id=>byId(T,id)),tr.gk.map(pkById),tr.tk.map(pkById));tr.msg=r.msg;tr.ok=r.ok;if(r.ok){tr.give=[];tr.get=[];tr.gk=[];tr.tk=[];}render();},
  offerYes(){const o=S.offer,U=S.teams[S.user],T=S.teams[o.team];const r=proposeTrade(T,o.give.map(id=>byId(U,id)),o.get.map(id=>byId(T,id)),o.giveK.map(pkById),o.getK.map(pkById));S.offer=null;if(!r.ok)S.news.unshift('That offer fell through: '+r.msg);save();render();},
  offerNo(){S.offer=null;save();render();},
  newFr(){if(!UI.confirmNew){UI.confirmNew=true;render();return;}UI.confirmNew=false;try{localStorage.removeItem(KEY);}catch(e){}S=null;UI.sel=null;UI.setup=null;UI.tr={team:-1,give:[],get:[],gk:[],tk:[],msg:'',ok:false};render();},
  pbtab(d){setTab(d.t);},
  call(d){callPlay(listed()[+d.i]);},dcall(d){callDef(listed()[+d.i]);},snap(){snap();},change(){if(gm&&gm.phase==='presnap'&&gm.poss==='U'&&!gm.ko){gm.phase='huddle';renderPanel();}},juke(){juke();},dive(){dive();},sw(){switchCtl();if(gm&&gm.phase==='presnap')renderPanel();},
  pat(d){patPick(d.two==='1');},toss(d){tossCall(d.v==='1');},tossPick(d){tossPick(d.v==='1');},timeout(d){useTimeout(d.v||'U');},spike(){spike();},hurry(){toggleHurry();},same(){if(gm&&gm.lastPlay)callPlay(gm.lastPlay);},
  fake(d){callPlay(PB.find(p=>p.fake===d.v&&p.t==='pass'));},aud(d){if(gm&&gm.phase==='presnap'){gm.aud=d.v;gm.audK=null;renderPanel();}},audClose(){if(gm){gm.aud=null;gm.audK=null;renderPanel();}},
  audPick(d){const p=gm&&gm.audList&&gm.audList[+d.i];if(p)audible(p);},hotPick(d){if(gm){gm.audK=+d.k;renderPanel();}},hotRoute(d){if(gm&&gm.audK!=null)hotRoute(gm.audK,+d.i);},
  lateral(){userLateral('U');},replay(){if(gm&&gm.rec)startReplay([gm.rec]);},hl(){if(gm&&gm.hls&&gm.hls.length)startReplay(gm.hls);},
  rpPause(){if(gm&&gm.rp){gm.rp.paused=!gm.rp.paused;renderPanel();}},rpAng(){if(gm&&gm.rp){gm.rp.ang=(gm.rp.ang+1)%ANGLES.length;gm.camSnap=true;renderPanel();}},rpSlow(){if(gm&&gm.rp){gm.rp.spd=gm.rp.spd===1?0.35:1;renderPanel();}},
  rpRestart(){if(gm&&gm.rp)gm.rp.t=gm.rp.list[gm.rp.i].frames[0].t;},rpNext(){const R=gm&&gm.rp;if(R&&R.i<R.list.length-1){R.i++;rpLoad();renderPanel();}},rpExit(){endReplay();},
  koDeep(){kickoff('U',false);},koHit(){koMeterHit();},
  quick(){UI.quick={u:S.user>=0?S.user:31,o:S.user>=0?(S.teams.find(t=>t.id!==S.user&&t.conf!==S.teams[S.user].conf)||S.teams[0]).id:22,ql:2};render();$('#view').scrollTop=0;},quickBack(){UI.quick=null;render();},
  quickStart(){const q=UI.quick;if(!q||q.u===q.o)return;UI.quick=null;const H=S.teams[q.u],A=S.teams[q.o];startGame(A,true,'H',fixClash(A,'A',{T:H,key:'H'}),{quick:true,U:H,ql:q.ql});},koOnside(){kickoff('U',true);},onside(){if(gm&&gm.phase==='presnap'&&gm.ko){gm.onside=true;flash('Onside kick');renderPanel();}},
  drill(d){startDrill(d.k);},drillQuit(){if(gm&&gm.drill)finishDrill();},
  two(){const o=S.teams.find(t=>t.id!==S.user&&t.conf!==S.teams[S.user].conf)||S.teams[(S.user+1)%32];UI.two={h:S.user,a:o.id};render();$('#view').scrollTop=0;},twoBack(){UI.two=null;render();},
  twoStart(){const T=UI.two;if(!T||T.h===T.a)return;UI.two=null;const H=S.teams[T.h],A=S.teams[T.a];startGame(A,true,'H',fixClash(A,'A',{T:H,key:'H'}),{two:true,U:H});},spin(){spin();},simDrive(){if(gm&&gm.pro&&gm.phase==='presnap'&&!gm.ko){gm.phase='huddle';}simDrive();},kneel(){kneel();},flag(d){flagPick(d.v==='1');},introSkip(){endIntro();},voiceTest(){testVoices();},
  edCap(){const p=byId(S.teams[S.user],UI.sel);if(!p)return;const e=toggleCaptain(p);UI.edMsg=e||(p.cap?p.n+' is now a captain.':'Captaincy removed.');UI.edOk=!e;render();},
  edKr(){const p=byId(S.teams[S.user],UI.sel);if(!p)return;setReturner(p);UI.edMsg=p.n+' will return kickoffs.';UI.edOk=true;render();},cele(d){celebrate(+d.i);},
  toPro(){save();UI.tab='home';UI.setup=null;UI.quick=null;UI.two=null;UI.proMsg='';if(hasSave(KEYP)&&load('p')){render();$('#view').scrollTop=0;return;}S=null;UI.proNew=true;render();$('#view').scrollTop=0;},
  toFr(){save();UI.tab='home';UI.proNew=false;UI.proMsg='';if(!load('f'))S=null;render();$('#view').scrollTop=0;},
  pnOpen(){UI.proNew=true;render();$('#view').scrollTop=0;},pnBack(){UI.proNew=false;if(hasSave(KEYP)&&load('p')){}else if(!load('f'))S=null;render();},
  pnPos(d){pnRead();UI.pn.pos=d.k;render();},
  pnGo(){pnRead();const P=UI.pn;if(P.start==='nfl')newPro(P.n,P.pos,P.num===''?-1:+P.num,+P.t);else newRoadPro(P.n,P.pos,P.num===''?-1:+P.num,P.hs);UI.proNew=false;UI.tab='home';UI.proMsg='';render();$('#view').scrollTop=0;},
  proUp(d){const e=proUpgrade(d.k);const p=proP();UI.proMsg=e||(d.k==='spd'?'Speed is now '+p.spd+'.':'You are now '+p.ovr+' overall.');UI.proOk=!e;render();},
  proAdv(){proAdvance();UI.proMsg='';render();$('#view').scrollTop=0;},
  proRet(){if(!UI.confirmRet){UI.confirmRet=true;render();return;}UI.confirmRet=false;proRetire(false);render();$('#view').scrollTop=0;},
  proTr(){const sel=$('#proTeam');const e=proTrade(sel?+sel.value:-1);UI.proMsg=e||'You have been traded to '+S.teams[S.user].name+'.';UI.proOk=!e;render();$('#view').scrollTop=0;},
  pnNew(){if(!UI.confirmNew){UI.confirmNew=true;render();return;}UI.confirmNew=false;try{localStorage.removeItem(KEYP);}catch(e){}S=null;UI.proNew=true;UI.pn=null;render();$('#view').scrollTop=0;},
  cont(){cardGo();},punt(){punt();},fg(){tryFG(false);},kick(){kickNow();},simRest(){simRest();}};
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-a]');if(!el)return;const f=ACT[el.dataset.a];if(f)f(el.dataset);});
document.addEventListener('keydown',ev=>{if(ev.key!=='Enter')return;const el=ev.target.closest&&ev.target.closest('tr[data-a]');if(el)ACT[el.dataset.a](el.dataset);else if(ev.target.id==='edName'||ev.target.id==='edNum')ACT.edSave();});
document.addEventListener('change',ev=>{const t=ev.target;
  if(t.id==='trTeam'){const tr=UI.tr;tr.team=+t.value;tr.get=[];tr.tk=[];tr.msg='';render();}
  else if(t.id==='setDiff'){S.diff=+t.value;save();}else if(t.id==='setSpeed'){S.speed=+t.value;save();}else if(t.id==='setDef'){S.playDef=t.value==='1';save();}else if(t.id==='setKo'){S.koRet=t.value==='1';save();}else if(t.id==='setTalk'){S.talk=+t.value;if(S.talk<2)hush();if(S.talk===3){const c=document.getElementById('cap');if(c)c.hidden=true;}save();}
  else if(t.id==='setV0'||t.id==='setV1'){const w=S.voice||['',''];w[t.id==='setV0'?0:1]=t.value;S.voice=w;voices=null;save();testVoices();}else if(t.id==='setVspd'){S.vspd=+t.value;save();testVoices();}else if(t.id==='setCrowd'){S.crowd=t.value==='1';save();}else if(t.id==='setQlen'){S.qlen=QLENS[+t.value]||4;save();}
  else if(t.id==='qkU'||t.id==='qkO'||t.id==='qkQl'){if(UI.quick){if(t.id==='qkQl')UI.quick.ql=QLENS[+t.value]||2;else UI.quick[t.id==='qkU'?'u':'o']=+t.value;render();}}
  else if(t.id==='pnTeam')pnRead();
  else if(t.id==='twoH'||t.id==='twoA'){if(UI.two){UI.two[t.id==='twoH'?'h':'a']=+t.value;render();}}});
document.addEventListener('input',ev=>{const t=ev.target;if(t.id==='pnName'||t.id==='pnNum')pnRead();});
initInput();load();render();
try{if(window.speechSynthesis)speechSynthesis.addEventListener('voiceschanged',()=>{voices=null;const a=document.activeElement;if(!gm&&S&&S.user>=0&&UI.tab==='home'&&!UI.setup&&!(a&&/SELECT|INPUT/.test(a.tagName)))render();});}catch(e){}

// ===== Be a Pro screens =====
const pnDef=()=>UI.pn||(UI.pn={n:'',pos:'WR',num:'',t:-1,start:'hs',hs:''});
function pnRead(){const P=pnDef(),a=$('#pnName'),b=$('#pnNum'),c=$('#pnTeam'),d=$('#pnHS');if(a)P.n=a.value;if(b)P.num=b.value;if(c)P.t=+c.value;if(d)P.hs=d.value;}
function proCard(){const has=hasSave(KEYP);return `<section class="card"><p class="eyebrow">Be a Pro</p><h3>Play one player's career</h3><p class="muted">Create a rookie and play only his snaps. The coach calls the plays, you make them. Earn XP each game, spend skill points to get better, and chase the Hall of Fame.</p><div class="row"><button class="btn${S&&S.user>=0?' ghost':''}" data-a="${has||S&&S.user>=0?'toPro':'pnOpen'}">${has?'Continue your career':'Create a player'}</button></div></section>`;}
function proNewCard(){const P=pnDef(),teams=S.teams.slice().sort((a,b)=>a.name.localeCompare(b.name));
  return `<section class="card hero"><p class="eyebrow">Be a Pro</p><h2>One player. One career.</h2><p class="muted">You only control your own player. On offense the coach calls the plays and the computer runs everyone else; when it's your turn to have the ball, it's all you. When your side is off the field, the game moves along without you.</p></section>
  <section class="card"><h3>Where you start</h3><div class="posgrid two">${[['hs','High school','Senior year. Earn a scholarship, play college ball, then hear your name called at the draft.'],['nfl','NFL rookie','Skip ahead and start as a first-year pro.']].map(([k,n,d])=>`<button class="posb${P.start===k?' on':''}" data-a="pnStart" data-k="${k}" aria-pressed="${P.start===k}"><b>${n}</b><small>${d}</small></button>`).join('')}</div></section>
  <section class="card"><h3>Your position</h3><div class="posgrid">${PRO_POS.map(([k,n,d])=>`<button class="posb${P.pos===k?' on':''}" data-a="pnPos" data-k="${k}" aria-pressed="${P.pos===k}"><b>${n}</b><small>${d}</small></button>`).join('')}</div></section>
  <section class="card"><h3>Your player</h3><div class="pform"><label><span>Name</span><input id="pnName" maxlength="22" autocomplete="off" placeholder="First and last name" value="${esc(P.n)}"></label><label><span>Number</span><input id="pnNum" type="number" min="0" max="99" inputmode="numeric" placeholder="Any" value="${esc(P.num)}"></label>
  ${P.start==='nfl'?`<label><span>Team</span><select id="pnTeam"><option value="-1">Let the draft decide</option>${teams.map(T=>`<option value="${T.id}"${P.t===T.id?' selected':''}>${T.name}</option>`).join('')}</select></label>`:`<label><span>High school</span><input id="pnHS" maxlength="24" autocomplete="off" placeholder="Any name, like Lincoln" value="${esc(P.hs)}"></label>`}</div>
  <p class="muted">${P.start==='nfl'?'You start as a 21-year-old rookie, about 70 overall, and you start every game. If the draft decides, one of the weaker teams picks you in the first round.':'You start as a 17-year-old senior, about 56 overall, and you start every game. Play well for scholarship offers, pick your college, and after your junior or senior year, declare for the NFL Draft.'}</p>
  <div class="row"><button class="btn" data-a="pnGo">Start your career</button><button class="btn ghost" data-a="${hasSave(KEY)||hasSave(KEYP)?'pnBack':'pnBack'}">Back</button></div></section>`;}
function proSettingsRow(){const sel=(id,lab,opts,cur)=>`<span class="setp"><label for="${id}">${lab}</label><select id="${id}">${opts.map((o,i)=>`<option value="${i}"${cur===i?' selected':''}>${o}</option>`).join('')}</select></span>`;
  return '<div class="row set">'+sel('setDiff','Difficulty',DIFFS,S.diff)+sel('setSpeed','Game speed',SPEEDS,S.speed)+sel('setTalk','Broadcast crew',['Off','Captions only','Voice and captions','Voice only'],S.talk)+sel('setQlen','Quarter length',QLENS.map(m=>m+' minutes'),Math.max(0,QLENS.indexOf(S.qlen||4)))+'</div>';}
function renderPro(){if(onRoad())return renderRoad();const p=proP(),P=S.pro,T=S.teams[S.user];P.xfs=P.xfs||[];if(!p){S.pro.done={n:'Unknown',pos:'WR',ovr:0,num:0,hist:[],aw:[]};}
  const q=proP();$('#top').innerHTML=`<div class="who">${sw(T,'lg')}<div><h1>${esc(q.n)}</h1><div class="meta">#${q.num} · ${q.pos} · ${P.done?'Retired':esc(T.name)} · ${S.season} · ${phaseName()}</div></div></div><div class="stat">${q.ovr}<small>Overall</small></div>`;
  if(!['home','team','league'].includes(UI.tab))UI.tab='home';
  $('#tabs').hidden=false;$('#tabs').innerHTML=[['home','Career'],['team','Team'],['league','League']].map(t=>`<button data-a="tab" data-t="${t[0]}" class="${UI.tab===t[0]?'on':''}">${t[1]}</button>`).join('');
  ({home:vPro,team:vProTeam,league:vLeague})[UI.tab]();}
function proPlayerCard(p){const P=S.pro,c=proCost(p),cs=proSpdCost(p),pct=Math.round(P.xp/PRO_XP*100);
  return `<section class="card procard"><div class="pc-top"><div class="pc-num">${p.num}</div><div><h3>${esc(p.n)}</h3><p class="muted">${PRO_POS.find(x=>x[0]===p.pos)[1]} · age ${p.age} · ${devTag(p)} potential${p.xf?` · <span class="xf">X</span> ${xfName(p)}`:''}</p></div></div>
  <div class="pc-stats"><div><b>${p.ovr}</b><small>Overall</small></div><div><b>${p.spd}</b><small>Speed</small></div><div><b>${P.sp}</b><small>Skill points</small></div><div><b>${P.games}</b><small>Games</small></div></div>
  <div class="xpbar" role="progressbar" aria-valuemin="0" aria-valuemax="${PRO_XP}" aria-valuenow="${P.xp}" aria-label="XP toward the next skill point"><span style="width:${pct}%"></span></div><p class="muted">${P.xp} of ${PRO_XP} XP to the next skill point.</p>
  ${P.done?'':`<div class="row"><button class="btn sm" data-a="proUp" data-k="ovr"${c&&P.sp>=c?'':' disabled'}>${c?'+1 overall ('+c+' pt'+(c>1?'s':'')+')':'Overall maxed'}</button><button class="btn ghost sm" data-a="proUp" data-k="spd"${cs&&P.sp>=cs?'':' disabled'}>${cs?'+1 speed ('+cs+' pt'+(cs>1?'s':'')+')':'Speed maxed'}</button>${UI.proMsg?`<span class="${UI.proOk?'good':'bad'}">${esc(UI.proMsg)}</span>`:''}</div>`}${proXFBlock(p)}</section>`;}
function vPro(){const p=proP(),P=S.pro,T=S.teams[S.user],r=ratings(T);let h='<div class="wrap">';
  if(P.done){const d=P.done,c=careerLine(d);
    h+=`<section class="card hero"><p class="eyebrow">Career over</p><h2>${esc(d.n)} retires</h2><p>${esc(c)}.</p>${(d.aw||[]).length?`<p><b>Awards:</b> ${awSum(d.aw)}</p>`:'<p class="muted">No major awards.</p>'}<p class="${d.hof?'good':'muted'}">${d.hof?'Inducted into the Hall of Fame.':'Not inducted into the Hall of Fame.'}</p><div class="row"><button class="btn" data-a="pnNew">${UI.confirmNew?'Tap again to start over':'Start a new pro'}</button>${hasSave(KEY)?'<button class="btn ghost" data-a="toFr">Go to your franchise</button>':''}</div></section>`;
    h+=`<section class="card"><h3>Career</h3>${careerTable(d)||'<p class="muted">No seasons recorded.</p>'}</section>`+(S.road&&S.road.car.length?`<section class="card"><h3>Before the pros</h3>${roadHist()}</section>`:'')+historyCards();$('#view').innerHTML=h+'</div>';return;}
  if(S.phase==='offseason'){const ch=S.teams[S.champ],others=S.teams.filter(t=>t.id!==S.user).sort((a,b)=>a.name.localeCompare(b.name));
    h+=`<section class="card hero"><p class="eyebrow">${S.season} season complete</p><h2>${ch.id===S.user?'You won the Gridiron Bowl!':esc(ch.name)+' won the Gridiron Bowl'}</h2><p>Your season: ${esc(statLine(p,T))}.</p><p class="muted">Next season you'll be ${p.age+1}. Young players get better every offseason; after about 30, they start to slow down. The league drafts and fills rosters for you.</p>
    <div class="row"><button class="btn" data-a="proAdv">Start the ${S.season+1} season</button>${p.age>=30?`<button class="btn ghost" data-a="proRet">${UI.confirmRet?'Tap again to retire':'Retire'}</button>`:''}</div>
    </section>`;}
  else{const m=userMatch(),lab=S.phase==='regular'?'Week '+(S.week+1)+' of '+S.schedule.length:roundName();
    if(m&&UI.setup)h+=setupCard(lab).replace(settingsRow(),proSettingsRow());
    else if(m){const home=m.h===S.user,opp=S.teams[home?m.a:m.h];
      h+=`<section class="card hero"><p class="eyebrow">${lab} · ${home?'Home':'Away'}</p><div class="match">${teamBlock(T,r)}<span class="vs">${home?'vs':'at'}</span>${teamBlock(opp,ratings(opp))}</div>
      <p class="eyebrow">Game goals · 50 XP each</p><ul class="news goals">${(P.goals||[]).map(g=>`<li>${esc(g.t)}</li>`).join('')}</ul>
      <div class="row"><button class="btn" data-a="play">Play game</button><button class="btn ghost" data-a="sim">Sim game</button></div><p class="muted">A simmed game earns ${35} XP, plus 15 for a win. Playing earns XP for everything you do.</p></section>`;}
    else if(S.phase==='regular')h+=`<section class="card hero"><p class="eyebrow">${lab}</p><h2>Bye week</h2><p class="muted">No game this week. Rest up.</p><div class="row"><button class="btn" data-a="sim">Continue</button></div></section>`;
    else{const alive=S.po&&(S.po.alive.A.includes(S.user)||S.po.alive.N.includes(S.user));h+=`<section class="card hero"><p class="eyebrow">${lab}</p><h2>${alive?'First-round bye':'Your season is over'}</h2><p class="muted">${alive?'Your team earned a week off.':'Your team missed out. Watch the rest of the playoffs.'}</p><div class="row"><button class="btn" data-a="sim">${alive?'Continue':'Sim this round'}</button></div></section>`;}}
  if(!UI.setup)h+=proPlayerCard(p)+proTradeCard(p);
  const L=P.last;if(L&&!UI.setup)h+=`<section class="card"><h3>Last game</h3><p><b>${esc(L.res)}</b>${L.sim?' · simmed':''}</p>${L.line?`<p>${esc(L.line)}</p>`:''}${(L.goals||[]).length?'<ul class="news goals">'+L.goals.map(g=>`<li class="${g.ok?'good':'muted'}">${g.ok?'✓':'✗'} ${esc(g.t)}</li>`).join('')+'</ul>':''}<p class="muted">+${L.xp} XP${L.sp?' · '+L.sp+' new skill point'+(L.sp>1?'s':''):''}</p></section>`;
  if(!UI.setup){h+=`<section class="card"><h3>${S.season} season</h3><p>${esc(proSeasonLine(p,T))}${S.week&&S.phase==='regular'&&S.week>(S.gpU||0)?' <span class="muted">(simmed games are estimated)</span>':''}</p>${careerTable(p)}${(p.aw||[]).length?`<p><b>Awards:</b> ${awSum(p.aw)}</p>`:''}</section>`;
    if(S.road&&S.road.car.length)h+=`<section class="card"><h3>Before the pros</h3>${roadHist()}${S.road.draft?`<p class="muted">${S.road.draft.pick?'Drafted: '+esc(S.road.draft.txt):'Undrafted free agent'}.</p>`:''}</section>`;
    if(S.news.length)h+='<section class="card"><h3>News</h3><ul class="news">'+S.news.slice(0,8).map(n=>`<li>${esc(n)}</li>`).join('')+'</ul></section>';
    h+=`<section class="card"><h3>Settings</h3>${proSettingsRow()}</section><section class="card"><h3>Broadcast sound</h3>${voiceRow()}</section>`;
    h+=`<section class="card"><h3>How Be a Pro works</h3><ul class="news"><li><b>You are one player.</b> A gold marker and YOU sit over him. Only he takes your controls.</li><li><b>Quarterback:</b> you call the plays and throw, just like franchise mode. After a handoff or a catch, the computer runs with it.</li><li><b>Running back, receiver or tight end:</b> the coach calls the play and tells you your job. Press Ready (Space) to snap. Routes run on their own; when the ball comes to you, it's yours: move, juke (Space), spin (E) and pitch (L).</li><li><b>Defense:</b> the coach picks the call; you play it. Move with WASD or the arrows, dive or swat with Space.</li><li><b>When your side is off the field</b>, the other half of the game is simulated so you only play your own snaps. Kicks are automatic.</li><li><b>XP:</b> every catch, yard, tackle and touchdown earns XP, each game goal met earns 50, and a win adds 25. Every ${PRO_XP} XP is a skill point to spend on overall or speed.</li><li><b>Seasons:</b> awards are based on how you play. Retire any time after 30, or play until 40, and see if you make the Hall of Fame.</li></ul>
    <div class="row">${hasSave(KEY)?'<button class="btn ghost sm" data-a="toFr">Go to your franchise</button>':''}<button class="btn ghost sm" data-a="pnNew">${UI.confirmNew?'Tap again to erase this career':'Start a new pro'}</button></div></section>`;}
  $('#view').innerHTML=h+'</div>';}
function vProTeam(){const T=onRoad()?S.road.team:S.teams[S.user],r=ratings(T),me=S.pro.id;let h=`<div class="wrap"><section class="card"><div class="match">${teamBlock(T,r)}</div><p class="muted">Your coach runs the roster. Starters are marked.</p><div class="scroll"><table class="tbl"><thead><tr><th class="l">Pos</th><th>#</th><th class="l">Player</th><th>Age</th><th>Ovr</th><th>Spd</th></tr></thead><tbody>`;
  for(const p of T.roster.slice().sort((a,b)=>posRank(a)-posRank(b))){const st=isStarter(T,p);h+=`<tr class="${p.id===me?'me':''}"><td class="l">${p.pos}</td><td>${p.num}</td><td class="l">${st?'<b>':''}${esc(p.n)}${st?'</b>':''}${xfTag(p)}${p.id===me?' <span class="chip">You</span>':''}${p.inj?' <span class="tag inj">Out '+p.inj+'</span>':''}</td><td>${p.age}</td><td>${p.ovr}</td><td>${p.spd}</td></tr>`;}
  $('#view').innerHTML=h+'</tbody></table></div></section></div>';}

function proPanel(g,kb){const ph=g.phase,uo=g.poss==='U',P=g.pro,pe=proEnt();if(g.ko||!pe)return null;
  const call=uo?g.play.n:DCALLS[g.defCall].n,sim='<button class="btn ghost sm" data-a="simDrive">Sim drive</button>';
  if(ph==='presnap'&&(!uo||P.pos!=='QB'))return `<div class="row"><button class="btn" data-a="snap">Ready${kb('Space')}</button>${sim}<span class="muted">Coach's call: <b>${esc(call)}</b>. ${proJob(g)}</span></div>`;
  if(ph!=='live'||g.loose)return null;const c=g.carrier,b=g.ball;
  if(c===pe&&(g.ret||g.mode==='run'))return coarse?`<div class="pad"><span class="muted">${g.ret?'Run it back! ':''}Drag to steer.</span><span class="row"><button class="btn ghost" data-a="lateral">Pitch</button><button class="btn ghost" data-a="spin">Spin</button><button class="btn" data-a="juke">Juke</button></span></div>`:`<div class="row"><span class="muted">${g.ret?'Run it back! ':'It\'s yours! '}Move: WASD or arrows. Juke: Space. Spin: E or F. Pitch it back: L.</span></div>`;
  if(c===pe)return null;
  if(g.ctl===pe&&!(c&&c.team==='U'))return coarse?`<div class="pad"><span class="muted">${g.ret?'Chase him down! ':''}Drag to move.</span><span class="row"><button class="btn" data-a="dive">Tackle</button></span></div>`:`<div class="row"><span class="muted">${g.ret?'Chase him down! ':''}Move: WASD or arrows. Dive tackle${uo?'':' or swat a pass'}: Space.</span></div>`;
  return `<div class="row"><span class="muted">${b&&b.fly&&b.target===pe?'Here it comes. Look for it!':uo?'Keep working. You take over if the ball comes to you.':'Your teammate has it.'}</span></div>`;}

function awSum(a){const m=new Map();for(const x of a)m.set(x,(m.get(x)||0)+1);return [...m].map(([k,n])=>(n>1?n+'× ':'')+esc(k)).join(' · ');}
function proXFBlock(p){const P=S.pro;P.xfs=P.xfs||[];if(p.xf&&!P.xfs.includes(p.xf))P.xfs.push(p.xf);const n=P.xfs.length,need=PRO_XF_OVR[n];
  return `<div class="xfrow"><p class="eyebrow">X-Factors</p><p class="muted">Unlock up to three for ${PRO_XF_COST} skill points each, at ${PRO_XF_OVR.join(', ')} overall. Equip one at a time. ${XFON[p.pos]}</p><div class="xfgrid">${XFS[p.pos].map(([k,nm,d])=>{const own=P.xfs.includes(k),on=p.xf===k;
    return `<div class="xfc${on?' on':''}"><b>${on?'<span class="xf">X</span> ':''}${nm}</b><small>${d}</small>${P.done?'':on?'<span class="chip">Equipped</span>':own?`<button class="btn ghost sm" data-a="proXF" data-k="${k}">Equip</button>`:n>=3?'':`<button class="btn ghost sm" data-a="proXF" data-k="${k}"${p.ovr>=need&&P.sp>=PRO_XF_COST?'':' disabled'}>${p.ovr>=need?'Unlock · '+PRO_XF_COST+' pts':'Unlocks at '+need}</button>`}</div>`;}).join('')}</div></div>`;}
function proTradeCard(p){if(S.pro.done||onRoad())return '';const open=proTradeOpen(),su=open?proSuitors():[];
  return `<section class="card"><h3>Request a trade</h3>${!open?`<p class="muted">The trade deadline has passed. Requests open again in the offseason.</p>`:su.length?`<p class="muted">These teams would start you at ${p.pos}. Trades go through right away.</p><div class="row"><select id="proTeam" aria-label="Team to be traded to">${su.map(t=>`<option value="${t.id}">${t.name} (${t.w}-${t.l}, ${ratings(t).ovr} OVR)</option>`).join('')}</select><button class="btn ghost sm" data-a="proTr">Request trade</button></div>`:`<p class="muted">No team would start you over their ${p.pos} right now. Raise your overall and ask again.</p>`}</section>`;}
function roadHist(){const R=S.road,p=proP();if(!R||!R.car||!R.car.length)return '';return `<div class="scroll"><table class="tbl sm"><thead><tr><th class="l">Season</th><th>Record</th><th>GP</th><th class="l">Stats</th><th class="l">Honors</th></tr></thead><tbody>${R.car.map(c=>`<tr><td class="l">${esc(c.lab)}</td><td>${c.w}-${c.l}</td><td>${c.gp}</td><td class="l">${esc(proLine(c.st,p.pos))}</td><td class="l">${c.aw.map(esc).join(', ')||'—'}</td></tr>`).join('')}</tbody></table></div>`;}
function renderRoad(){const R=S.road,p=proP(),T=R.team;S.pro.xfs=S.pro.xfs||[];
  $('#top').innerHTML=`<div class="who">${sw(T,'lg')}<div><h1>${esc(p.n)}</h1><div class="meta">#${p.num} · ${p.pos} · ${esc(roadLabel())}</div></div></div><div class="stat">${p.ovr}<small>Overall</small></div>`;
  if(!['home','team'].includes(UI.tab))UI.tab='home';$('#tabs').hidden=false;
  $('#tabs').innerHTML=[['home','Career'],['team','Team']].map(t=>`<button data-a="tab" data-t="${t[0]}" class="${UI.tab===t[0]?'on':''}">${t[1]}</button>`).join('');
  (UI.tab==='team'?vProTeam:vRoad)();}
const stars=n=>'<span class="stars" aria-label="'+n+' stars">'+'★'.repeat(n)+'<span>'+'★'.repeat(5-n)+'</span></span>';
function vRoad(){const R=S.road,p=proP(),T=R.team,P=S.pro,m=roadMatch(),hs=R.stage==='hs';let h='<div class="wrap">';
  if(m){h+=`<section class="card hero"><p class="eyebrow">${esc(roadLabel())} · ${esc(m.lab)} · ${m.home?'Home':'Away'}</p><div class="match">${teamBlock(T,ratings(T))}<span class="vs">${m.home?'vs':'at'}</span>${teamBlock(m.opp,ratings(m.opp))}</div>
    <p class="eyebrow">Game goals · 50 XP each</p><ul class="news goals">${(P.goals||[]).map(g=>`<li>${esc(g.t)}</li>`).join('')}</ul>
    <div class="row"><button class="btn" data-a="play">Play game</button><button class="btn ghost" data-a="sim">Sim game</button><button class="btn ghost sm" data-a="roadAll">Sim the rest of the season</button></div>
    <p class="muted">${hs?'College scouts are in the stands. ':'NFL scouts are watching. '}Playing earns XP for everything you do; a simmed game earns 40, plus 10 for a win.</p></section>`;}
  else if(R.stage==='hs'||R.stage==='col'){const s=R.sea,nx=R.stage==='col'?R.yr+1:0;
    h+=`<section class="card hero"><p class="eyebrow">${esc(roadLabel())} · season over</p><h2>${T.w}-${T.l}${s.champ?' · '+esc(s.champ):''}</h2><p>${esc(proLine(s.st,p.pos))} in ${s.gp} games.</p>${s.aw.length?`<p><b>Honors:</b> ${s.aw.map(esc).join(' · ')}</p>`:'<p class="muted">No honors this year.</p>'}
    <div class="row">${hs?'<button class="btn" data-a="roadNext">See your scholarship offers</button>':R.yr<2?`<button class="btn" data-a="roadNext">Start your ${CLASS_YR[nx].toLowerCase()} year</button>`:`<button class="btn" data-a="roadDeclare">Declare for the NFL Draft</button>${R.yr===2?'<button class="btn ghost" data-a="roadNext">Come back for your senior year</button>':''}`}</div>
    ${!hs&&R.yr>=2?`<p class="muted">Draft outlook: ${roadProjection().txt}.</p>`:''}</section>`;}
  else if(R.stage==='offers'){h+=`<section class="card hero"><p class="eyebrow">Recruiting</p><h2>${stars(R.stars)} ${R.stars}-star prospect</h2><p class="muted">Pick where you play college ball. Bigger programs play tougher schedules, win more, and get more national attention at draft time.</p></section>
    <div class="offers">${R.offers.map(i=>{const c=COLLEGES[i];return `<section class="card offer"><div class="tb"><span class="sw lg" style="--a:${c[2]};--b:${c[3]}"></span><div><b>${esc(c[0])}</b><span>Program ${stars(Math.max(1,Math.round(c[4]/2)))}</span></div></div><button class="btn sm" data-a="roadCommit" data-k="${i}">Commit</button></section>`;}).join('')}</div>`;}
  else if(R.stage==='draft'){const pr=roadProjection(),D=R.draft;
    h+=D?`<section class="card hero"><p class="eyebrow">${S.season} NFL Draft · ${esc(D.txt)}</p><h2>${D.pick?'With pick '+D.pick+', '+esc(S.teams[D.tid].name)+' select '+esc(p.n):esc(p.n)+' signs with '+esc(S.teams[D.tid].name)}</h2><div class="match">${teamBlock(S.teams[D.tid],ratings(S.teams[D.tid]))}</div><div class="row"><button class="btn" data-a="roadNFL">Start your NFL career</button></div></section>`
      :`<section class="card hero"><p class="eyebrow">${S.season} NFL Draft</p><h2>Draft day</h2><p>Scouts project you as ${pr.txt}.</p><div class="row"><button class="btn" data-a="roadDraft">Go to the draft</button></div></section>`;}
  h+=proPlayerCard(p);
  const L=P.last;if(L)h+=`<section class="card"><h3>Last game</h3><p><b>${esc(L.res)}</b>${L.sim?' · simmed':''}</p>${L.line?`<p>${esc(L.line)}</p>`:''}${(L.goals||[]).length?'<ul class="news goals">'+L.goals.map(g=>`<li class="${g.ok?'good':'muted'}">${g.ok?'✓':'✗'} ${esc(g.t)}</li>`).join('')+'</ul>':''}<p class="muted">+${L.xp} XP${L.sp?' · '+L.sp+' new skill point'+(L.sp>1?'s':''):''}</p></section>`;
  if(m&&R.sea)h+=`<section class="card"><h3>This season</h3><p>${T.w}-${T.l} · ${esc(R.sea.gp?proLine(R.sea.st,p.pos):'No games yet')}</p></section>`;
  if(R.car.length)h+=`<section class="card"><h3>Before the pros</h3>${roadHist()}</section>`;
  if(S.news.length)h+='<section class="card"><h3>News</h3><ul class="news">'+S.news.slice(0,8).map(n=>`<li>${esc(n)}</li>`).join('')+'</ul></section>';
  h+=`<section class="card"><h3>Settings</h3>${proSettingsRow()}</section><section class="card"><h3>Road to the Pros</h3><ul class="news"><li><b>High school:</b> one senior season of 8 games, plus the state playoffs if you win 5. Your play and honors decide your star rating and which colleges offer.</li><li><b>College:</b> 10 games a year. Win 6 for a bowl game; win 9 for the playoff and a shot at the national title. Big seasons earn All-Conference, All-American and the Heisman.</li><li><b>The draft:</b> declare after your junior or senior year. Your overall and college honors decide where you go.</li><li>XP and skill points work the same as in the NFL, and you can unlock X-Factors once you reach ${PRO_XF_OVR[0]} overall.</li></ul>
    <div class="row">${hasSave(KEY)?'<button class="btn ghost sm" data-a="toFr">Go to your franchise</button>':''}<button class="btn ghost sm" data-a="pnNew">${UI.confirmNew?'Tap again to erase this career':'Start a new pro'}</button></div></section>`;
  $('#view').innerHTML=h+'</div>';}
function roadPlay(){const R=S.road,m=roadMatch(),p=proP();if(!m)return;const T=R.team,uU=m.home?'H':'A',uO=fixClash(m.opp,m.home?'A':'H',{T,key:uU});
  startGame(m.opp,m.home,uU,uO,{U:T,road:true,pro:{id:p.id,pos:p.pos,n:p.n}});}
function roadSim(){const m=roadMatch(),R=S.road,P=S.pro;if(!m)return;const T=R.team,sc=m.home?simGame(T,m.opp):simGame(m.opp,T),us=m.home?sc[0]:sc[1],th=m.home?sc[1]:sc[0],xp=40+(us>th?10:0);
  P.games++;const sp=proGain(xp);P.last={sim:true,xp,sp,res:(us>th?'Won ':'Lost ')+us+'-'+th};proGoals();roadResult(us,th,null);}
